--
-- Name: create_employee_impl(uuid, text, uuid, uuid, uuid, text, text, text, public.app_role[], date, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.create_employee_impl(p_actor uuid, p_path text, p_company_id uuid, p_department_id uuid, p_manager_id uuid, p_personnel_no text, p_full_name text, p_password text, p_roles public.app_role[], p_hire_date date, p_language_pref text, p_calendar_pref text, p_job_title text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid       uuid := gen_random_uuid();
  v_pno       text := btrim(coalesce(p_personnel_no, ''));
  v_dept_code text;
  v_code      text;
  v_email     text;
  v_role      public.app_role;
begin
  if v_pno !~ '^[0-9]{1,10}$' then
    raise exception 'invalid personnel number (1-10 digits)' using errcode = '22023';
  end if;
  if length(coalesce(p_password, '')) < 8 then
    raise exception 'new password must be at least 8 characters' using errcode = '22023';
  end if;
  if coalesce(btrim(p_full_name), '') = '' then
    raise exception 'full name is required' using errcode = '22023';
  end if;
  if p_department_id is null then
    raise exception 'department is required' using errcode = '22023';
  end if;

  -- The department no longer feeds the code, but it must still exist and
  -- belong to this company: it scopes the team and defaults the manager.
  select code into v_dept_code
    from public.departments
   where id = p_department_id and company_id = p_company_id;
  if v_dept_code is null then
    raise exception 'department not found' using errcode = '22023';
  end if;

  v_code := v_pno;
  if exists (select 1 from public.profiles where company_id = p_company_id and personnel_no = v_pno) then
    raise exception 'personnel number already exists' using errcode = '23505';
  end if;
  -- employee_code uniqueness is GLOBAL, not per company. With bare numbers a
  -- second tenant's 1042 would collide; see the spec §6 for the multi-tenant
  -- cost this knowingly takes on.
  if exists (select 1 from public.profiles where employee_code = v_code) then
    raise exception 'employee code already exists' using errcode = '23505';
  end if;

  v_email := v_code || '@bj-app.internal';

  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    created_at, updated_at, raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token
  ) values (
    '00000000-0000-0000-0000-000000000000', v_uid, 'authenticated', 'authenticated', v_email,
    extensions.crypt(p_password, extensions.gen_salt('bf')), now(), now(), now(),
    '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, false, false,
    '', '', '', '', '', '', '', ''
  );

  insert into auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (v_uid::text, v_uid,
          jsonb_build_object('sub', v_uid::text, 'email', v_email, 'email_verified', true),
          'email', now(), now(), now());

  insert into public.profiles (id, company_id, employee_code, full_name, department_id, manager_id,
                               hire_date, language_pref, calendar_pref, personnel_no, job_title)
  values (v_uid, p_company_id, v_code, btrim(p_full_name), p_department_id, p_manager_id,
          p_hire_date, coalesce(p_language_pref, 'fa'), coalesce(p_calendar_pref, 'jalali'),
          v_pno, nullif(btrim(coalesce(p_job_title, '')), ''));

  foreach v_role in array p_roles loop
    insert into public.user_roles (user_id, role) values (v_uid, v_role) on conflict do nothing;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (p_actor, 'create_employee', 'profiles', v_uid,
          jsonb_build_object('employee_code', v_code, 'personnel_no', v_pno,
                             'full_name', p_full_name, 'roles', to_jsonb(p_roles), 'path', p_path));

  return v_uid;
end; $_$;


--
-- Name: department_manager_for(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.department_manager_for(p_emp uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select d.manager_id
    from public.profiles p
    join public.departments d on d.id = p.department_id
    join public.profiles m on m.id = d.manager_id and m.active
   where p.id = p_emp;
$$;


--
-- Name: department_step_applies(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.department_step_applies(p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select x.dm is not null
     and x.dm <> p_emp
     and x.dm is distinct from (select manager_id from public.profiles where id = p_emp)
    from (select private.department_manager_for(p_emp) as dm) x;
$$;


--
-- Name: enforce_department_update_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_department_update_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if new.manager_id is not null
     and (tg_op = 'INSERT' or new.manager_id is distinct from old.manager_id)
     and not exists (
       select 1 from public.profiles where id = new.manager_id and company_id = new.company_id
     )
  then
    raise exception 'department manager must belong to the same company' using errcode = '22023';
  end if;

  if tg_op = 'INSERT' or private.is_admin(v_uid) then
    return new;
  end if;

  if (new.id         is distinct from old.id)
     or (new.company_id is distinct from old.company_id)
     or (new.code       is distinct from old.code)
     or (new.kind       is distinct from old.kind)
     or (new.created_at is distinct from old.created_at)
  then
    raise exception 'not permitted to modify restricted department fields' using errcode = '42501';
  end if;

  if new.manager_id is distinct from old.manager_id
     and exists (select 1 from public.profiles where id = v_uid and department_id = old.id)
  then
    raise exception 'you cannot change the manager of your own department' using errcode = '42501';
  end if;

  return new;
end; $$;


--
-- Name: enforce_profile_update_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_profile_update_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_allowed text[];
begin
  if coalesce(current_setting('bj.separation_apply', true), '') = 'on'
     and old.active and not new.active
     and (to_jsonb(new) - 'active') = (to_jsonb(old) - 'active')
  then
    return new;
  end if;

  if private.is_admin(v_uid) then
    return new;  -- admins may change anything
  end if;

  if new.id = v_uid then
    v_allowed := array['full_name', 'language_pref', 'calendar_pref'];
  elsif private.has_permission(v_uid, 'employees.edit')
        and old.company_id = (select company_id from public.profiles where id = v_uid)
        -- An admin's record is admin-only, even while that admin is deactivated
        -- (so an editor cannot reactivate one): check the role row, not is_admin.
        and not exists (select 1 from public.user_roles where user_id = old.id and role = 'admin')
  then
    v_allowed := array['full_name', 'hire_date', 'department_id', 'manager_id', 'job_title', 'active'];
  elsif private.is_manager_of(v_uid, new.id) then
    v_allowed := array['full_name', 'hire_date'];
  else
    raise exception 'not permitted to update this profile' using errcode = '42501';
  end if;

  if (new.id            is distinct from old.id)
     or (new.company_id    is distinct from old.company_id)
     or (new.employee_code is distinct from old.employee_code)
     or (new.personnel_no  is distinct from old.personnel_no)
     or (new.created_at    is distinct from old.created_at)
     or (new.must_change_password is distinct from old.must_change_password
         and coalesce(current_setting('bj.password_flag_write', true), '') <> 'on')
     or (new.full_name     is distinct from old.full_name     and not ('full_name'     = any (v_allowed)))
     or (new.hire_date     is distinct from old.hire_date     and not ('hire_date'     = any (v_allowed)))
     or (new.department_id is distinct from old.department_id and not ('department_id' = any (v_allowed)))
     or (new.manager_id    is distinct from old.manager_id    and not ('manager_id'    = any (v_allowed)))
     or (new.job_title     is distinct from old.job_title     and not ('job_title'     = any (v_allowed)))
     or (new.active        is distinct from old.active        and not ('active'        = any (v_allowed)))
     or (new.language_pref is distinct from old.language_pref and not ('language_pref' = any (v_allowed)))
     or (new.calendar_pref is distinct from old.calendar_pref and not ('calendar_pref' = any (v_allowed)))
  then
    raise exception 'not permitted to modify restricted profile fields' using errcode = '42501';
  end if;

  return new;
end; $$;


--
-- Name: has_permission(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_permission(uid uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_permission
    when 'employees.edit'     then private.is_admin(uid) or private.has_role(uid, 'hr')
    when 'departments.edit'   then private.is_admin(uid) or private.has_role(uid, 'hr')
    when 'accruals.run'       then private.is_admin(uid) or private.has_role(uid, 'hr')
    when 'roles.manager'      then private.is_admin(uid) or private.has_role(uid, 'hr')
    when 'personal_info.view' then private.is_admin(uid) or private.has_role(uid, 'hr')
    when 'personal_info.edit' then private.is_admin(uid) or private.has_role(uid, 'hr')
    when 'separations.manage' then private.is_admin(uid) or private.has_role(uid, 'hr')
    when 'separations.view'   then private.is_admin(uid) or private.has_role(uid, 'hr')
                                   or private.has_role(uid, 'finance')
    else false
  end;
$$;


--
-- Name: has_role(uuid, public.app_role); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_role(uid uuid, r public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and exists (
       select 1
         from public.user_roles
        where user_id = uid
          and role = r
     );
$$;


--
-- Name: is_active(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_active(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.profiles
     where id = uid
       and active
  );
$$;


--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_admin(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'admin');
$$;


--
-- Name: is_company_weekend(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_company_weekend(p_company_id uuid, p_date date) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_weekly   int[];
  v_biweekly int[];
  v_anchor   date;
  v_dow      int;
begin
  if p_date is null then return false; end if;

  select coalesce(weekend_days, '{5}'),
         coalesce(biweekly_weekend_days, '{}'),
         biweekly_anchor
    into v_weekly, v_biweekly, v_anchor
    from public.work_settings
   where company_id = p_company_id
   limit 1;

  -- No settings row: same fallback the callers have always used (Friday only).
  if v_weekly is null then
    v_weekly := '{5}';
    v_biweekly := '{}';
  end if;

  v_dow := extract(isodow from p_date)::int;

  if v_dow = any(v_weekly) then
    return true;
  end if;

  if v_anchor is null or array_length(v_biweekly, 1) is null then
    return false;
  end if;

  if v_dow <> all(v_biweekly) then
    return false;
  end if;

  -- Whole weeks between the two dates' week buckets, on a Saturday-aligned grid.
  -- floor() division matters: `/` on integers truncates toward zero in Postgres,
  -- so a date BEFORE the epoch would bucket wrongly without it. The epoch is far
  -- in the past, but relying on that is the kind of assumption that breaks once.
  return mod(
           abs(
             floor((p_date  - date '2000-01-01') / 7.0)::int
             - floor((v_anchor - date '2000-01-01') / 7.0)::int
           ),
           2
         ) = 0;
end;
$$;


--
-- Name: FUNCTION is_company_weekend(p_company_id uuid, p_date date); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.is_company_weekend(p_company_id uuid, p_date date) IS 'FR-41: single source of truth for "is this date a non-working weekend day for this company". Mirrored in lib/leave/weekend.ts.';


--
-- Name: is_department_manager_of(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_department_manager_of(p_uid uuid, p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_uid is not null
     and private.is_active(p_uid)
     and private.department_manager_for(p_emp) = p_uid;
$$;


--
-- Name: is_manager_of(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_manager_of(uid uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'manager')
     and exists (
       select 1
         from public.profiles caller
         join public.profiles employee
           on employee.id = target
          and employee.company_id = caller.company_id
        where caller.id = uid
          and employee.manager_id = uid
     );
$$;


--
-- Name: is_valid_card_no(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_card_no(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_sum int := 0;
  v_d   int;
begin
  if p is null or p !~ '^[0-9]{16}$' then return false; end if;
  for i in 1..16 loop
    v_d := substr(p, i, 1)::int;
    if i % 2 = 1 then            -- 16 digits: odd positions from the left are doubled
      v_d := v_d * 2;
      if v_d > 9 then v_d := v_d - 9; end if;
    end if;
    v_sum := v_sum + v_d;
  end loop;
  return v_sum % 10 = 0;
end; $_$;


--
-- Name: is_valid_national_id(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_national_id(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_sum int := 0;
  v_rem int;
  v_chk int;
begin
  if p is null or p !~ '^[0-9]{10}$' then return false; end if;
  -- All-same-digit numbers pass the arithmetic but are never issued.
  if p ~ '^(.)\1{9}$' then return false; end if;
  for i in 1..9 loop
    v_sum := v_sum + substr(p, i, 1)::int * (11 - i);
  end loop;
  v_rem := v_sum % 11;
  v_chk := substr(p, 10, 1)::int;
  return (v_rem < 2 and v_chk = v_rem) or (v_rem >= 2 and v_chk = 11 - v_rem);
end; $_$;


--
-- Name: is_valid_sheba(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_sheba(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_digits text;
  v_rem    int := 0;
begin
  if p is null or p !~ '^IR[0-9]{24}$' then return false; end if;
  v_digits := substr(p, 5) || '1827' || substr(p, 3, 2);
  for i in 1..length(v_digits) loop
    v_rem := (v_rem * 10 + substr(v_digits, i, 1)::int) % 97;
  end loop;
  return v_rem = 1;
end; $_$;


--
-- Name: personal_info_before_update(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.personal_info_before_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.employee_id is distinct from old.employee_id
     or new.company_id is distinct from old.company_id then
    raise exception 'not permitted to modify restricted personal info fields' using errcode = '42501';
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end; $$;


--
-- Name: preserve_active_admin(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preserve_active_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.active
     and not new.active
     and exists (
       select 1 from public.user_roles
        where user_id = old.id and role = 'admin'
     )
     and not exists (
       select 1
         from public.profiles p
         join public.user_roles r on r.user_id = p.id and r.role = 'admin'
        where p.active
          and p.id <> old.id
     )
  then
    raise exception 'cannot deactivate the last active admin' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: profiles_create_personal_info(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.profiles_create_personal_info() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.employee_personal_info (employee_id, company_id)
  values (new.id, new.company_id)
  on conflict (employee_id) do nothing;
  return new;
end; $$;


--
-- Name: refresh_separation_status(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_separation_status(p_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.separations s
     set status = 'awaiting_finance'
   where s.id = p_id
     and s.status = 'in_progress'
     and not exists (select 1 from public.separation_signoffs o
                      where o.separation_id = s.id and o.signed_at is null);
$$;


--
-- Name: replacement_is_away(uuid, date, date, public.leave_unit, time without time zone, time without time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.replacement_is_away(p_replacement_id uuid, p_start date, p_end date, p_unit public.leave_unit, p_start_time time without time zone, p_end_time time without time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.leave_requests r
     where r.employee_id = p_replacement_id
       and r.status in ('pending', 'approved')
       and r.start_date <= p_end
       and r.end_date >= p_start
       and (
         r.unit = 'day' or p_unit = 'day'
         or (r.start_time < p_end_time and r.end_time > p_start_time)
       )
  );
$$;


--
-- Name: same_team(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.same_team(uid uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and exists (
       select 1
         from public.profiles caller
         join public.profiles teammate
           on teammate.id = target
          and teammate.company_id = caller.company_id
          and teammate.department_id = caller.department_id
        where caller.id = uid
          and caller.department_id is not null
     );
$$;


--
-- Name: separation_caller_company(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_caller_company(p_uid uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(p_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  return (select company_id from public.profiles where id = p_uid);
end; $$;


--
-- Name: separation_check_fields(text, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_check_fields(p_reason text, p_last_day date, p_note text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_reason is null
     or p_reason not in ('resignation', 'dismissal', 'contract_end', 'abandonment', 'redundancy') then
    raise exception 'invalid reason' using errcode = '22023';
  end if;
  if p_last_day is null then
    raise exception 'last working day is required' using errcode = '22023';
  end if;
  if p_note is not null and length(p_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
end; $$;


--
-- Name: separation_check_signature(text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_check_signature(p_data text, p_authorized boolean) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if not coalesce(p_authorized, false) then
    raise exception 'signature authorization is required' using errcode = '22023';
  end if;
  if p_data is null or p_data = '' then
    raise exception 'signature is required' using errcode = '22023';
  end if;
  if length(p_data) not between 100 and 350000
     or mod(length(p_data), 4) <> 2
     or p_data !~ '^data:image/png;base64,iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$' then
    raise exception 'signature data is invalid' using errcode = '22023';
  end if;
end; $_$;


--
-- Name: separation_manageable(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_manageable(p_uid uuid, p_company uuid, p_employee uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.has_permission(p_uid, 'separations.manage') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_employee and company_id = p_company) then
    raise exception 'employee not found' using errcode = '42501';
  end if;
  if not private.is_admin(p_uid)
     and exists (select 1 from public.user_roles where user_id = p_employee and role = 'admin') then
    raise exception 'not allowed to file a clearance form for this employee' using errcode = '42501';
  end if;
end; $$;


--
-- Name: separation_row_signer(uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_row_signer(p_company uuid, p_employee uuid, p_row jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_dept   uuid := nullif(p_row->>'department_id', '')::uuid;
  v_signer uuid := nullif(p_row->>'signer_id', '')::uuid;
begin
  if jsonb_typeof(p_row) <> 'object'
     or coalesce(char_length(btrim(p_row->>'name_fa')), 0) not between 1 and 100
     or coalesce(char_length(btrim(p_row->>'name_en')), 0) not between 1 and 100 then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  if v_dept is not null
     and not exists (select 1 from public.departments where id = v_dept and company_id = p_company) then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  if v_signer is not null then
    if v_signer = p_employee then
      raise exception 'the departing employee cannot sign their own form' using errcode = '22023';
    end if;
    if not exists (select 1 from public.profiles
                    where id = v_signer and company_id = p_company and active) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    return v_signer;
  end if;
  if v_dept is not null then
    select d.manager_id into v_signer
      from public.departments d
      join public.profiles m on m.id = d.manager_id and m.active
     where d.id = v_dept;
    if v_signer = p_employee then
      return null;
    end if;
    return v_signer;
  end if;
  return null;
end; $$;


--
-- Name: step_applies(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.step_applies(p_scope text, p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_scope is distinct from 'department' or private.department_step_applies(p_emp);
$$;


--
-- Name: submit_leave_impl(uuid, date, date, public.day_part, text, public.leave_unit, time without time zone, time without time zone, uuid, public.request_kind, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.submit_leave_impl(p_leave_type_id uuid, p_start date, p_end date, p_day_part public.day_part, p_reason text, p_unit public.leave_unit, p_start_time time without time zone, p_end_time time without time zone, p_replacement_id uuid, p_kind public.request_kind, p_location text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
  v_dept uuid;
  v_minutes int;
  v_affects boolean;
  v_is_paid boolean;
  v_allow_hourly boolean;
  v_balance int;
  v_unpaid int := 0;
  v_req uuid;
  v_win_start time;
  v_win_end time;
  v_cap int;
  v_day_used int;
  v_jyear int;
  v_seq int;
  v_location text := nullif(btrim(p_location), '');
  v_replacement uuid;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  select company_id, department_id into v_company, v_dept
    from public.profiles where id = v_uid;
  if v_company is null then raise exception 'no profile for caller' using errcode = '42501'; end if;

  if p_start is null or p_end is null then
    raise exception 'start and end dates are required' using errcode = '22023';
  end if;
  if p_end < p_start then
    raise exception 'end date must not be before start date' using errcode = '22023';
  end if;
  if p_end - p_start > 366 then
    raise exception 'date range too long' using errcode = '22023';
  end if;

  if p_kind = 'errand' then
    if v_location is null then
      raise exception 'errand location is required' using errcode = '22023';
    end if;
    if length(v_location) > 200 then
      raise exception 'errand location is too long' using errcode = '22023';
    end if;
    if p_unit = 'hour' then
      if p_start <> p_end
         or p_start_time is null
         or p_end_time is null
         or p_end_time <= p_start_time
      then
        raise exception 'end time must be after start time' using errcode = '22023';
      end if;
    elsif p_unit = 'day' then
      if p_start_time is not null or p_end_time is not null or p_day_part <> 'full' then
        raise exception 'daily errands require full dates without times' using errcode = '22023';
      end if;
    end if;
    v_replacement := null;
  else
    if p_leave_type_id is null then
      raise exception 'invalid or inactive leave type' using errcode = '22023';
    end if;
    v_location := null;
    v_replacement := p_replacement_id;
  end if;

  if p_kind = 'leave' then
    select affects_balance, is_paid, allow_hourly
      into v_affects, v_is_paid, v_allow_hourly
      from public.leave_types
     where id = p_leave_type_id and company_id = v_company and active;
    if v_affects is null then
      raise exception 'invalid or inactive leave type' using errcode = '22023';
    end if;
  end if;

  if p_kind = 'leave' and p_unit = 'hour' then
    if not coalesce(v_allow_hourly, false) then
      raise exception 'this leave type cannot be taken hourly' using errcode = '22023';
    end if;
    if p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
      raise exception 'end time must be after start time' using errcode = '22023';
    end if;

    select work_start, work_end, max_hourly_minutes_per_day
      into v_win_start, v_win_end, v_cap
      from public.work_settings where company_id = v_company limit 1;
    v_win_start := coalesce(v_win_start, '07:00'::time);
    v_win_end := coalesce(v_win_end, '15:00'::time);
    v_cap := coalesce(v_cap, 240);

    if p_start_time < v_win_start or p_end_time > v_win_end then
      raise exception 'times must fall within working hours' using errcode = '22023';
    end if;
    if (extract(epoch from (p_end_time - p_start_time)) / 60)::int > v_cap then
      raise exception 'hourly leave exceeds the daily limit' using errcode = '22023';
    end if;
  end if;

  if v_replacement is not null then
    if not exists (
      select 1 from public.profiles p
       where p.id = v_replacement
         and p.active
         and p.company_id = v_company
         and v_dept is not null
         and p.department_id = v_dept
         and p.id <> v_uid
    ) then
      raise exception 'replacement must be an active colleague in your department'
        using errcode = '22023';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));

  if p_kind = 'leave' and p_unit = 'hour' then
    select coalesce(sum(r.requested_minutes), 0) into v_day_used
      from public.leave_requests r
     where r.employee_id = v_uid
       and r.kind = 'leave'
       and r.unit = 'hour'
       and r.start_date = p_start
       and r.status in ('pending', 'approved');

    if v_day_used + (extract(epoch from (p_end_time - p_start_time)) / 60)::int > v_cap then
      raise exception 'hourly leave exceeds the daily limit' using errcode = '22023';
    end if;
  end if;

  if exists (
    select 1 from public.leave_requests r
     where r.employee_id = v_uid
       and r.status in ('pending', 'approved')
       and r.start_date <= p_end
       and r.end_date >= p_start
       and (
         r.unit = 'day' or p_unit = 'day'
         or (r.start_time < p_end_time and r.end_time > p_start_time)
       )
  ) then
    raise exception 'overlapping leave request exists' using errcode = '22023';
  end if;

  if v_replacement is not null
     and private.replacement_is_away(
       v_replacement, p_start, p_end, p_unit, p_start_time, p_end_time
     )
  then
    raise exception 'replacement is on leave during this period' using errcode = '22023';
  end if;

  v_minutes := public.compute_requested_minutes(
    v_company, p_start, p_end, p_day_part, p_unit, p_start_time, p_end_time, p_kind
  );
  if v_minutes <= 0 then
    raise exception 'requested days must be greater than 0 (all days fall on weekend/holiday or dates invalid)'
      using errcode = '22023';
  end if;

  if v_affects then
    v_balance := public.current_leave_balance(v_uid, p_leave_type_id);
    v_unpaid := greatest(v_minutes - greatest(v_balance, 0), 0);
  elsif p_kind = 'leave' and not coalesce(v_is_paid, false) then
    v_unpaid := v_minutes;
  end if;

  select jm.jalali_year into v_jyear
    from public.jalali_months jm
   where p_start between jm.gregorian_start and jm.gregorian_end;
  if v_jyear is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  insert into public.leave_request_serials(company_id, jalali_year, kind, last_seq)
  values (v_company, v_jyear, p_kind, 1)
  on conflict (company_id, jalali_year, kind) do update
     set last_seq = public.leave_request_serials.last_seq + 1
  returning last_seq into v_seq;

  insert into public.leave_requests(
    employee_id, leave_type_id, start_date, end_date, day_part,
    unit, start_time, end_time, requested_minutes, unpaid_minutes, status, reason,
    replacement_id, company_id, serial_year, serial_seq, kind, errand_location
  )
  values (
    v_uid, p_leave_type_id, p_start, p_end, p_day_part,
    p_unit, p_start_time, p_end_time, v_minutes, v_unpaid, 'pending', p_reason,
    v_replacement, v_company, v_jyear, v_seq, p_kind, v_location
  )
  returning id into v_req;

  return v_req;
end;
$$;


--
-- Name: user_signatures_touch(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.user_signatures_touch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at := now();
  return new;
end; $$;


--
-- Name: accrue_all_leave(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_all_leave() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p            record;
  v_employees    int := 0;
  v_rows_before  int;
  v_rows_after   int;
  v_last_emp     uuid;
begin
  if not private.has_permission(auth.uid(), 'accruals.run') then
    raise exception 'not allowed to post accruals' using errcode = '42501';
  end if;

  select count(*) into v_rows_before from public.leave_ledger where period_month is not null;

  for v_p in
    select p.employee_id, p.leave_type_id
      from public.employee_leave_policies p
      join public.profiles pr on pr.id = p.employee_id
     where pr.active
       and p.accrual_minutes_per_month > 0
     order by p.employee_id
  loop
    perform public.accrue_leave(v_p.employee_id, v_p.leave_type_id);
    if v_last_emp is null or v_last_emp <> v_p.employee_id then
      v_employees := v_employees + 1;
      v_last_emp := v_p.employee_id;
    end if;
  end loop;

  select count(*) into v_rows_after from public.leave_ledger where period_month is not null;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'accrue_all_leave', 'leave_ledger', null,
          jsonb_build_object('employees', v_employees, 'rows_posted', v_rows_after - v_rows_before));

  return jsonb_build_object('employees', v_employees, 'rows_posted', v_rows_after - v_rows_before);
end; $$;


--
-- Name: accrue_employee_leave(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_employee_leave(p_employee_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_type uuid;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  -- FR-43: hr joins manager-of and admin. This posts only months the policy has
  -- ALREADY earned — it credits nothing that was not due — and it runs lazily on
  -- every balance read. Without hr here, the balances HR now reads on the Edit
  -- Employee screen would silently lag behind the accrual policy HR just set.
  if not (private.is_manager_of(v_uid, p_employee_id)
          or private.is_admin(v_uid)
          or private.has_role(v_uid, 'hr')) then
    raise exception 'not allowed to accrue for this employee' using errcode = '42501';
  end if;

  for v_type in
    select leave_type_id from public.employee_leave_policies where employee_id = p_employee_id
  loop
    perform public.accrue_leave(p_employee_id, v_type);
  end loop;
end; $$;


--
-- Name: accrue_leave(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_leave(p_employee_id uuid, p_leave_type_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rate      int;
  v_cap       int;
  v_carry     int;
  v_start     date;
  v_hire      date;
  v_today     date := (now() at time zone 'Asia/Tehran')::date;
  v_this_mon  date;
  v_first_post date;
  v_balance   int;
  v_m         record;
  v_amount    int;
  v_already   int;
  v_excess    int;
  v_earlier   boolean;
  v_rows      int;
begin
  select accrual_minutes_per_month, annual_cap_minutes, carryover_cap_minutes, accrual_start_month
    into v_rate, v_cap, v_carry, v_start
    from public.employee_leave_policies
   where employee_id = p_employee_id and leave_type_id = p_leave_type_id;

  -- No policy, or a non-accruing type (sick leave): nothing to do.
  if v_rate is null or v_rate <= 0 then
    return public.current_leave_balance(p_employee_id, p_leave_type_id);
  end if;

  -- Hot-path short-circuit: this runs on every balance read, so if the month
  -- containing today is already posted there is nothing to do and we skip both
  -- the lock and the loop. Steady-state cost is one indexed EXISTS.
  select gregorian_start into v_this_mon
    from public.jalali_months
   where v_today between gregorian_start and gregorian_end;

  -- The oldest month actually posted. If the policy's start is now EARLIER
  -- than this, an admin has backdated accrual_start_month and the months in
  -- between were never credited, so the short-circuit below must not fire.
  select min(period_month) into v_first_post
    from public.leave_ledger
   where employee_id = p_employee_id and leave_type_id = p_leave_type_id
     and entry_type = 'allocation' and period_month is not null;

  if v_this_mon is not null
     and (v_first_post is null or v_first_post <= v_start)
     and exists (
       select 1 from public.leave_ledger
        where employee_id = p_employee_id and leave_type_id = p_leave_type_id
          and entry_type = 'allocation' and period_month = v_this_mon
     )
  then
    return public.current_leave_balance(p_employee_id, p_leave_type_id);
  end if;

  -- Serialize with every other leave write for this employee (2026-07-02 hardening).
  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee_id::text, 0));

  select hire_date into v_hire from public.profiles where id = p_employee_id;
  v_balance := public.current_leave_balance(p_employee_id, p_leave_type_id);

  for v_m in
    select jm.jalali_year, jm.jalali_month, jm.gregorian_start, jm.gregorian_end
      from public.jalali_months jm
     where jm.gregorian_start >= v_start
       and jm.gregorian_start <= v_today
     order by jm.gregorian_start
  loop
    -- Nobody accrues for a month that ended before they were hired.
    if v_hire is not null and v_m.gregorian_end < v_hire then
      continue;
    end if;

    -- Year boundary: clamp the carried balance BEFORE crediting this month.
    if v_m.jalali_month = 1 then
      select exists (
        select 1 from public.leave_ledger
         where employee_id = p_employee_id and leave_type_id = p_leave_type_id
           and entry_type = 'allocation' and period_month is not null
           and period_month < v_m.gregorian_start
      ) into v_earlier;

      if v_earlier and v_balance > v_carry then
        v_excess := v_balance - v_carry;
        insert into public.leave_ledger(employee_id, leave_type_id, entry_type,
                                        delta_minutes, balance_after_minutes, period_month, note)
        values (p_employee_id, p_leave_type_id, 'carryover_forfeit',
                -v_excess, v_carry, v_m.gregorian_start, 'carryover above cap forfeited')
        on conflict do nothing;
        -- Only move the running balance if the row was actually written; a
        -- concurrent caller may have posted it first.
        get diagnostics v_rows = row_count;
        if v_rows = 1 then
          v_balance := v_carry;
        end if;
      end if;
    end if;

    v_amount := v_rate;

    -- Pro-rate the hire month by calendar days remaining in it.
    if v_hire is not null and v_hire between v_m.gregorian_start and v_m.gregorian_end then
      v_amount := round(v_rate::numeric
                        * ((v_m.gregorian_end - v_hire) + 1)
                        / ((v_m.gregorian_end - v_m.gregorian_start) + 1));
    end if;

    -- The annual cap counts ACCRUALS within this Jalali year, not the balance.
    -- Opening allocations have a null period_month and so never consume it.
    if v_cap is not null then
      select coalesce(sum(l.delta_minutes), 0) into v_already
        from public.leave_ledger l
        join public.jalali_months jm on jm.gregorian_start = l.period_month
       where l.employee_id = p_employee_id and l.leave_type_id = p_leave_type_id
         and l.entry_type = 'allocation'
         and jm.jalali_year = v_m.jalali_year;
      v_amount := least(v_amount, greatest(v_cap - v_already, 0));
    end if;

    if v_amount > 0 then
      insert into public.leave_ledger(employee_id, leave_type_id, entry_type,
                                      delta_minutes, balance_after_minutes, period_month, note)
      values (p_employee_id, p_leave_type_id, 'allocation',
              v_amount, v_balance + v_amount, v_m.gregorian_start, 'monthly accrual')
      on conflict do nothing;
      get diagnostics v_rows = row_count;
      if v_rows = 1 then
        v_balance := v_balance + v_amount;
      end if;
    end if;
  end loop;

  return v_balance;
end; $$;


--
-- Name: accrue_my_leave(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_my_leave() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_type uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  for v_type in
    select leave_type_id
      from public.employee_leave_policies
     where employee_id = v_uid
  loop
    perform public.accrue_leave(v_uid, v_type);
  end loop;
end;
$$;


--
-- Name: allocate_leave(uuid, uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_leave(p_employee_id uuid, p_leave_type_id uuid, p_period_start date, p_period_end date, p_minutes integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- FR-43: admin OR hr. HR administers leave, so the two screens that set an
  -- opening balance and an accrual policy are theirs as well.
  if not (private.is_admin(auth.uid()) or private.has_role(auth.uid(), 'hr')) then
    raise exception 'only admins or hr can allocate leave' using errcode = '42501';
  end if;
  -- ...but nobody except an admin does it to THEMSELVES. Same asymmetry FR-36
  -- already applies to signing your own request: an admin is the owner and may,
  -- an HR officer granting themselves leave is an obvious control weakness.
  if not private.is_admin(auth.uid()) and p_employee_id = auth.uid() then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;
  return private.allocate_leave_impl(auth.uid(), p_employee_id, p_leave_type_id,
                                     p_period_start, p_period_end, p_minutes);
end; $$;


--
-- Name: app_bulk_create_employees(uuid, jsonb, jsonb, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_create_employees(p_company_id uuid, p_rows jsonb, p_departments jsonb, p_balance_as_of date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_caller        uuid := auth.uid();
  v_bulk_hr       boolean;
  v_today         date := (now() at time zone 'Asia/Tehran')::date;
  v_dep           jsonb;
  v_row           jsonb;
  v_i             integer := 0;
  v_dept          uuid;
  v_mgr_pno       text;
  v_mgr           uuid;
  v_role          text;
  v_uid           uuid;
  v_code          text;
  v_minutes       int;
  v_prev          int;
  v_ledger        uuid;
  v_annual_type   uuid;
  v_rate          int;
  v_cap           int;
  v_carry         int;
  v_accrual_start date;
  v_dm            uuid;
  v_result        jsonb := '[]'::jsonb;
begin
  v_bulk_hr := private.has_role(v_caller, 'hr') and not private.is_admin(v_caller);
  if not (private.is_admin(v_caller) or v_bulk_hr) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;
  -- Tenant binding: the company comes from the request, so it must be the
  -- caller's own. Without this an admin of one company could import into another.
  if p_company_id is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'not allowed to import into another company' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if p_departments is null or jsonb_typeof(p_departments) <> 'array' then
    raise exception 'departments must be an array' using errcode = '22023';
  end if;
  if p_balance_as_of is null then
    raise exception 'balance date is required' using errcode = '22023';
  end if;
  if p_balance_as_of > v_today then
    raise exception 'balance date cannot be in the future' using errcode = '22023';
  end if;

  -- First Jalali month after the one containing the balance date. Raises
  -- through the join if the date is outside the seeded calendar.
  select n.gregorian_start into v_accrual_start
    from public.jalali_months m
    join public.jalali_months n on n.gregorian_start = m.gregorian_end + 1
   where p_balance_as_of between m.gregorian_start and m.gregorian_end;
  if v_accrual_start is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  select id, default_accrual_minutes_per_month, default_annual_cap_minutes, default_carryover_cap_minutes
    into v_annual_type, v_rate, v_cap, v_carry
    from public.leave_types
   where company_id = p_company_id and name_en = 'Annual Leave' and affects_balance;

  -- 1. Departments.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    v_code := upper(btrim(coalesce(v_dep->>'code', '')));
    if v_code !~ '^[A-Z0-9]{2,4}$' then
      raise exception 'invalid department code "%"', v_code using errcode = '22023';
    end if;
    if coalesce((v_dep->>'create')::boolean, false) then
      if v_bulk_hr then
        raise exception 'only admins can create departments' using errcode = '42501';
      end if;
      if exists (select 1 from public.departments where company_id = p_company_id and code = v_code) then
        raise exception 'department code "%" already exists', v_code using errcode = '23505';
      end if;
      if coalesce(btrim(v_dep->>'name_fa'), '') = '' or coalesce(btrim(v_dep->>'name_en'), '') = '' then
        raise exception 'department "%" needs a Farsi and an English name', v_code using errcode = '22023';
      end if;
      insert into public.departments (company_id, name_fa, name_en, kind, code)
      values (p_company_id, btrim(v_dep->>'name_fa'), btrim(v_dep->>'name_en'), 'team', v_code);
    end if;
  end loop;

  -- 2–4. Employees, opening balances, accrual policies.
  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;

    v_role := coalesce(v_row->>'role', 'employee');
    -- FR-35 / spec D4: HR may bulk-onboard, but only ordinary employees.
    if v_bulk_hr then
      v_role := 'employee';
    end if;
    if v_role not in ('manager', 'employee') then
      raise exception 'row %: role must be manager or employee', v_i using errcode = '22023';
    end if;

    select id into v_dept from public.departments
     where company_id = p_company_id and code = upper(btrim(coalesce(v_row->>'department_code', '')));
    if v_dept is null then
      raise exception 'row %: unknown department code "%"', v_i, v_row->>'department_code' using errcode = '22023';
    end if;

    v_mgr := null;
    v_mgr_pno := coalesce(nullif(btrim(coalesce(v_row->>'supervisor_personnel_no', '')), ''),
                          nullif(btrim(coalesce(v_row->>'manager_personnel_no', '')), ''));
    if v_mgr_pno is not null then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = v_mgr_pno;
      if v_mgr is null then
        raise exception 'row %: manager with personnel number % not found (list managers before their team)',
          v_i, v_mgr_pno using errcode = '22023';
      end if;
    end if;

    v_uid := private.create_employee_impl(
      v_caller, case when v_bulk_hr then 'bulk_hr' else 'bulk' end, p_company_id, v_dept, v_mgr,
      v_row->>'personnel_no', v_row->>'full_name', v_row->>'password',
      (case when v_role = 'manager' then array['manager','employee'] else array['employee'] end)::public.app_role[],
      nullif(v_row->>'hire_date', '')::date, 'fa', 'jalali', v_row->>'job_title');

    v_minutes := coalesce(nullif(v_row->>'balance_minutes', ''), '0')::int;
    if v_minutes < -366 * private.company_minutes_per_day(p_company_id)
       or v_minutes > 366 * private.company_minutes_per_day(p_company_id) then
      raise exception 'row %: opening balance is out of range', v_i using errcode = '22023';
    end if;
    if v_minutes <> 0 then
      if v_annual_type is null then
        raise exception 'row %: leave type "Annual Leave" not found', v_i using errcode = '22023';
      end if;
      perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
      v_prev := public.current_leave_balance(v_uid, v_annual_type);
      insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
      values (v_uid, v_annual_type, 'adjustment', v_minutes, v_prev + v_minutes,
              'opening balance as of ' || p_balance_as_of::text)
      returning id into v_ledger;
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
              jsonb_build_object('employee_id', v_uid, 'leave_type_id', v_annual_type,
                                 'minutes', v_minutes, 'as_of', p_balance_as_of));
    end if;

    if v_annual_type is not null and coalesce(v_rate, 0) > 0 then
      insert into public.employee_leave_policies (
        employee_id, leave_type_id, accrual_minutes_per_month,
        annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
      ) values (
        v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller
      )
      on conflict (employee_id, leave_type_id) do nothing;
    end if;

    select employee_code into v_code from public.profiles where id = v_uid;
    v_result := v_result || jsonb_build_object(
      'personnel_no', v_row->>'personnel_no', 'employee_code', v_code, 'user_id', v_uid);
  end loop;

  -- 5. Department managers — only where the department has none yet.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') = '' then
      continue;
    end if;
    if v_bulk_hr then
      raise exception 'only admins can assign department managers' using errcode = '42501';
    end if;
    select id into v_dm from public.profiles
     where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
    if v_dm is null then
      raise exception 'department manager with personnel number % not found',
        v_dep->>'manager_personnel_no' using errcode = '22023';
    end if;
    update public.departments
       set manager_id = v_dm
     where company_id = p_company_id
       and code = upper(btrim(v_dep->>'code'))
       and manager_id is null;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_caller, 'bulk_create_employees', 'profiles', null,
          jsonb_build_object('count', jsonb_array_length(p_rows),
                             'departments_created',
                             (select count(*) from jsonb_array_elements(p_departments) d
                               where coalesce((d->>'create')::boolean, false)),
                             'balance_as_of', p_balance_as_of));

  return v_result;
end;
$_$;


--
-- Name: app_bulk_import_employees(uuid, text, jsonb, jsonb, date, boolean, uuid[], jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_import_employees(p_company_id uuid, p_mode text, p_rows jsonb, p_departments jsonb, p_balance_as_of date, p_overwrite_balances boolean, p_deactivate uuid[], p_reassign jsonb, p_delete_departments text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_caller        uuid := auth.uid();
  v_is_admin      boolean;
  v_bulk_hr       boolean;
  v_today         date := (now() at time zone 'Asia/Tehran')::date;
  v_dep           jsonb;
  v_row           jsonb;
  v_i             integer := 0;
  v_dept          uuid;
  v_mgr_pno       text;
  v_mgr           uuid;
  v_role          text;
  v_uid           uuid;
  v_existing      uuid;
  v_code          text;
  v_minutes       int;
  v_prev          int;
  v_ledger        uuid;
  v_annual_type   uuid;
  v_rate          int;
  v_cap           int;
  v_carry         int;
  v_accrual_start date;
  v_dm            uuid;
  v_id            uuid;
  v_created       jsonb := '[]'::jsonb;
  v_updated       int := 0;
  v_deactivated   int := 0;
  v_deleted       text[] := '{}';
  v_not_deleted   text[] := '{}';
  v_mpd           int;
begin
  v_is_admin := private.is_admin(v_caller);
  v_bulk_hr  := private.has_role(v_caller, 'hr') and not v_is_admin;
  if not (v_is_admin or v_bulk_hr) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;
  -- Tenant binding: the company comes from the request, so it must be the
  -- caller's own. Without this an admin of one company could import into another.
  if p_company_id is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'not allowed to import into another company' using errcode = '42501';
  end if;
  if p_mode is null or p_mode not in ('add', 'update', 'replace') then
    raise exception 'import mode must be add, update or replace' using errcode = '22023';
  end if;
  if p_mode <> 'add' and not v_is_admin then
    raise exception 'only admins can update or replace employees by import' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if p_departments is null or jsonb_typeof(p_departments) <> 'array' then
    raise exception 'departments must be an array' using errcode = '22023';
  end if;
  if p_mode <> 'replace' and (coalesce(cardinality(p_deactivate), 0) > 0
       or coalesce(cardinality(p_delete_departments), 0) > 0
       or coalesce(jsonb_array_length(p_reassign), 0) > 0) then
    raise exception 'deactivation and department deletion need replace mode' using errcode = '22023';
  end if;
  if p_balance_as_of is null then
    raise exception 'balance date is required' using errcode = '22023';
  end if;
  if p_balance_as_of > v_today then
    raise exception 'balance date cannot be in the future' using errcode = '22023';
  end if;

  select n.gregorian_start into v_accrual_start
    from public.jalali_months m
    join public.jalali_months n on n.gregorian_start = m.gregorian_end + 1
   where p_balance_as_of between m.gregorian_start and m.gregorian_end;
  if v_accrual_start is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  select id, default_accrual_minutes_per_month, default_annual_cap_minutes, default_carryover_cap_minutes
    into v_annual_type, v_rate, v_cap, v_carry
    from public.leave_types
   where company_id = p_company_id and name_en = 'Annual Leave' and affects_balance;
  v_mpd := private.company_minutes_per_day(p_company_id);

  -- 1. Departments: create, or (update/replace) take the file's names.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    v_code := upper(btrim(coalesce(v_dep->>'code', '')));
    if v_code !~ '^[A-Z0-9]{2,4}$' then
      raise exception 'invalid department code "%"', v_code using errcode = '22023';
    end if;
    if coalesce((v_dep->>'create')::boolean, false) then
      if v_bulk_hr then
        raise exception 'only admins can create departments' using errcode = '42501';
      end if;
      if exists (select 1 from public.departments where company_id = p_company_id and code = v_code) then
        raise exception 'department code "%" already exists', v_code using errcode = '23505';
      end if;
      if coalesce(btrim(v_dep->>'name_fa'), '') = '' or coalesce(btrim(v_dep->>'name_en'), '') = '' then
        raise exception 'department "%" needs a Farsi and an English name', v_code using errcode = '22023';
      end if;
      insert into public.departments (company_id, name_fa, name_en, kind, code)
      values (p_company_id, btrim(v_dep->>'name_fa'), btrim(v_dep->>'name_en'), 'team', v_code);
    elsif p_mode <> 'add' and coalesce((v_dep->>'rename')::boolean, false) then
      update public.departments
         set name_fa = btrim(v_dep->>'name_fa'), name_en = btrim(v_dep->>'name_en')
       where company_id = p_company_id and code = v_code
         and coalesce(btrim(v_dep->>'name_fa'), '') <> '' and coalesce(btrim(v_dep->>'name_en'), '') <> '';
    end if;
  end loop;

  -- 2. Employees: create or update.
  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;

    v_role := coalesce(v_row->>'role', 'employee');
    if v_bulk_hr then
      v_role := 'employee';
    end if;
    if v_role not in ('manager', 'employee') then
      raise exception 'row %: role must be manager or employee', v_i using errcode = '22023';
    end if;

    select id into v_dept from public.departments
     where company_id = p_company_id and code = upper(btrim(coalesce(v_row->>'department_code', '')));
    if v_dept is null then
      raise exception 'row %: unknown department code "%"', v_i, v_row->>'department_code' using errcode = '22023';
    end if;

    v_mgr := null;
    v_mgr_pno := coalesce(nullif(btrim(coalesce(v_row->>'supervisor_personnel_no', '')), ''),
                          nullif(btrim(coalesce(v_row->>'manager_personnel_no', '')), ''));
    if v_mgr_pno is not null then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = v_mgr_pno;
      if v_mgr is null then
        raise exception 'row %: manager with personnel number % not found (list managers before their team)',
          v_i, v_mgr_pno using errcode = '22023';
      end if;
    end if;

    v_minutes := coalesce(nullif(v_row->>'balance_minutes', ''), '0')::int;
    if v_minutes < -366 * v_mpd or v_minutes > 366 * v_mpd then
      raise exception 'row %: opening balance is out of range', v_i using errcode = '22023';
    end if;

    select id into v_existing from public.profiles
     where company_id = p_company_id and personnel_no = btrim(coalesce(v_row->>'personnel_no', ''));

    if v_existing is not null then
      if p_mode = 'add' then
        raise exception 'personnel number already exists' using errcode = '23505';
      end if;
      v_uid := v_existing;

      update public.profiles
         set full_name     = btrim(v_row->>'full_name'),
             job_title     = nullif(btrim(coalesce(v_row->>'job_title', '')), ''),
             department_id = v_dept,
             manager_id    = v_mgr,
             hire_date     = coalesce(nullif(v_row->>'hire_date', '')::date, hire_date),
             active        = true
       where id = v_uid;

      -- Only the manager role follows the file; admin/hr/security are untouched.
      if v_role = 'manager' then
        insert into public.user_roles (user_id, role) values (v_uid, 'manager') on conflict do nothing;
      else
        delete from public.user_roles where user_id = v_uid and role = 'manager';
      end if;

      if coalesce(p_overwrite_balances, false) and v_annual_type is not null then
        perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
        v_prev := public.current_leave_balance(v_uid, v_annual_type);
        if v_prev <> v_minutes then
          insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
          values (v_uid, v_annual_type, 'adjustment', v_minutes - v_prev, v_minutes,
                  'opening balance as of ' || p_balance_as_of::text)
          returning id into v_ledger;
          insert into public.audit_log (actor_id, action, entity, entity_id, after)
          values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
                  jsonb_build_object('employee_id', v_uid, 'previous_minutes', v_prev,
                                     'minutes', v_minutes, 'as_of', p_balance_as_of));
        end if;
        if coalesce(v_rate, 0) > 0 then
          insert into public.employee_leave_policies (
            employee_id, leave_type_id, accrual_minutes_per_month,
            annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
          ) values (v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller)
          on conflict (employee_id, leave_type_id) do update
             set accrual_start_month = excluded.accrual_start_month;
        end if;
      end if;

      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_update_employee', 'profiles', v_uid,
              jsonb_build_object('personnel_no', v_row->>'personnel_no', 'mode', p_mode,
                                 'department_code', v_row->>'department_code', 'role', v_role));
      v_updated := v_updated + 1;
    else
      v_uid := private.create_employee_impl(
        v_caller, case when v_bulk_hr then 'bulk_hr' else 'bulk' end, p_company_id, v_dept, v_mgr,
        v_row->>'personnel_no', v_row->>'full_name', v_row->>'password',
        (case when v_role = 'manager' then array['manager','employee'] else array['employee'] end)::public.app_role[],
        nullif(v_row->>'hire_date', '')::date, 'fa', 'jalali', v_row->>'job_title');

      if v_minutes <> 0 then
        if v_annual_type is null then
          raise exception 'row %: leave type "Annual Leave" not found', v_i using errcode = '22023';
        end if;
        perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
        v_prev := public.current_leave_balance(v_uid, v_annual_type);
        insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
        values (v_uid, v_annual_type, 'adjustment', v_minutes, v_prev + v_minutes,
                'opening balance as of ' || p_balance_as_of::text)
        returning id into v_ledger;
        insert into public.audit_log (actor_id, action, entity, entity_id, after)
        values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
                jsonb_build_object('employee_id', v_uid, 'leave_type_id', v_annual_type,
                                   'minutes', v_minutes, 'as_of', p_balance_as_of));
      end if;

      if v_annual_type is not null and coalesce(v_rate, 0) > 0 then
        insert into public.employee_leave_policies (
          employee_id, leave_type_id, accrual_minutes_per_month,
          annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
        ) values (v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller)
        on conflict (employee_id, leave_type_id) do nothing;
      end if;

      select employee_code into v_code from public.profiles where id = v_uid;
      v_created := v_created || jsonb_build_object(
        'personnel_no', v_row->>'personnel_no', 'employee_code', v_code, 'user_id', v_uid);
    end if;
  end loop;

  -- 3. Kept people whose manager changes (replace).
  for v_dep in select * from jsonb_array_elements(coalesce(p_reassign, '[]'::jsonb)) loop
    v_id := (v_dep->>'id')::uuid;
    if not exists (select 1 from public.profiles where id = v_id and company_id = p_company_id) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
    v_mgr := null;
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') <> '' then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
      if v_mgr is null then
        raise exception 'manager with personnel number % not found', v_dep->>'manager_personnel_no' using errcode = '22023';
      end if;
    end if;
    update public.profiles set manager_id = v_mgr where id = v_id;
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_caller, 'bulk_reassign_manager', 'profiles', v_id, jsonb_build_object('manager_id', v_mgr));
  end loop;

  -- 4. Deactivations (replace). Never an admin, never the caller.
  foreach v_id in array coalesce(p_deactivate, '{}'::uuid[]) loop
    if not exists (select 1 from public.profiles where id = v_id and company_id = p_company_id) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
    if v_id = v_caller or exists (select 1 from public.user_roles where user_id = v_id and role = 'admin') then
      raise exception 'an import cannot deactivate an admin account' using errcode = '42501';
    end if;
    update public.profiles set active = false where id = v_id and active;
    if found then
      v_deactivated := v_deactivated + 1;
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_deactivate', 'profiles', v_id, jsonb_build_object('mode', p_mode));
    end if;
  end loop;

  -- 5. Department managers.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') = '' then
      continue;
    end if;
    if v_bulk_hr then
      raise exception 'only admins can assign department managers' using errcode = '42501';
    end if;
    select id into v_dm from public.profiles
     where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
    if v_dm is null then
      raise exception 'department manager with personnel number % not found',
        v_dep->>'manager_personnel_no' using errcode = '22023';
    end if;
    update public.departments d
       set manager_id = v_dm
     where d.company_id = p_company_id
       and d.code = upper(btrim(v_dep->>'code'))
       and (p_mode <> 'add'
            or d.manager_id is null
            or not exists (select 1 from public.profiles m where m.id = d.manager_id and m.active));
  end loop;

  -- 6. Unused departments (replace): delete only if nobody, active or not, is in them.
  foreach v_code in array coalesce(p_delete_departments, '{}'::text[]) loop
    select id into v_dept from public.departments where company_id = p_company_id and code = upper(btrim(v_code));
    if v_dept is null then
      continue;
    end if;
    if exists (select 1 from public.profiles where department_id = v_dept) then
      v_not_deleted := v_not_deleted || upper(btrim(v_code));
    else
      delete from public.departments where id = v_dept;
      v_deleted := v_deleted || upper(btrim(v_code));
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_delete_department', 'departments', v_dept, jsonb_build_object('code', upper(btrim(v_code))));
    end if;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_caller, 'bulk_import', 'profiles', null,
          jsonb_build_object('mode', p_mode, 'rows', jsonb_array_length(p_rows),
                             'created', jsonb_array_length(v_created), 'updated', v_updated,
                             'deactivated', v_deactivated, 'departments_deleted', to_jsonb(v_deleted),
                             'overwrite_balances', coalesce(p_overwrite_balances, false),
                             'balance_as_of', p_balance_as_of));

  return jsonb_build_object(
    'created', v_created,
    'updated', v_updated,
    'deactivated', v_deactivated,
    'deleted_departments', to_jsonb(v_deleted),
    'not_deleted_departments', to_jsonb(v_not_deleted)
  );
end;
$_$;


--
-- Name: app_bulk_set_employee_passwords(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_set_employee_passwords(p_resets jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_row   record;
  v_count int;
begin
  if not private.is_admin(v_uid) then
    raise exception 'only admins can reset passwords' using errcode = '42501';
  end if;
  if jsonb_typeof(p_resets) <> 'array' then
    raise exception 'password resets must be an array' using errcode = '22023';
  end if;

  v_count := jsonb_array_length(p_resets);
  if v_count < 1 or v_count > 100 then
    raise exception 'select between 1 and 100 employees' using errcode = '22023';
  end if;

  if (
    select count(*) <> count(distinct item->>'user_id')
      from jsonb_array_elements(p_resets) item
  ) then
    raise exception 'duplicate employee in password reset' using errcode = '22023';
  end if;

  -- Validate the complete payload before changing the first credential.
  for v_row in
    select (item->>'user_id')::uuid as user_id, item->>'password' as password
      from jsonb_array_elements(p_resets) item
  loop
    if v_row.user_id = v_uid then
      raise exception 'cannot bulk-reset your own password' using errcode = '22023';
    end if;
    if length(coalesce(v_row.password, '')) < 8 then
      raise exception 'new password must be at least 8 characters' using errcode = '22023';
    end if;
    if octet_length(coalesce(v_row.password, '')) > 72 then
      raise exception 'new password must be at most 72 ASCII characters' using errcode = '22023';
    end if;
    if not exists (
      select 1
        from auth.users u
        join public.profiles p on p.id = u.id
       where u.id = v_row.user_id
    ) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
  end loop;

  for v_row in
    select (item->>'user_id')::uuid as user_id, item->>'password' as password
      from jsonb_array_elements(p_resets) item
  loop
    update auth.users
       set encrypted_password = extensions.crypt(v_row.password, extensions.gen_salt('bf')),
           updated_at = now()
     where id = v_row.user_id;

    update public.profiles
       set must_change_password = true
     where id = v_row.user_id;

    insert into public.audit_log (actor_id, action, entity, entity_id)
    values (v_uid, 'reset_password', 'auth.users', v_row.user_id);
  end loop;
end;
$$;


--
-- Name: app_cancel_separation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_cancel_separation(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  s         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status = 'cancelled' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if s.deactivated_at is not null then
    raise exception 'form already applied' using errcode = '22023';
  end if;
  update public.separations set status = 'cancelled', cancelled_by = v_uid, cancelled_at = now()
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.cancel', 'separations', p_id, null);
end; $$;


--
-- Name: app_change_my_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_change_my_password(p_current text, p_new text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_ok  boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  if length(coalesce(p_new, '')) < 8 then
    raise exception 'new password must be at least 8 characters' using errcode = '22023';
  end if;
  if octet_length(coalesce(p_new, '')) > 72 then
    raise exception 'new password must be at most 72 ASCII characters' using errcode = '22023';
  end if;
  if p_new = p_current then
    raise exception 'new password must differ from the current password' using errcode = '22023';
  end if;

  select encrypted_password = extensions.crypt(p_current, encrypted_password)
    into v_ok
    from auth.users
   where id = v_uid;
  if not coalesce(v_ok, false) then
    raise exception 'current password is incorrect' using errcode = '42501';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_new, extensions.gen_salt('bf')),
         updated_at = now()
   where id = v_uid;

  perform set_config('bj.password_flag_write', 'on', true);
  update public.profiles
     set must_change_password = false
   where id = v_uid and must_change_password;
  perform set_config('bj.password_flag_write', '', true);

  insert into public.audit_log(actor_id, action, entity, entity_id)
  values (v_uid, 'change_own_password', 'auth.users', v_uid);
end;
$$;


--
-- Name: app_cleanup_e2e_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_cleanup_e2e_users() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_count integer;
  v_steps integer;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if not private.is_admin(v_uid) then
    raise exception 'admin role required' using errcode = '42501';
  end if;

  -- The junk predicate, unchanged from 20260702140000. Kept verbatim rather than
  -- factored out: it is the whole safety boundary of this function, and both
  -- shapes matter (see DATA_MODEL — codes before and after the prefix change).
  create temp table if not exists _e2e_junk on commit drop as
    select id from public.profiles
    where employee_code ~ '^(mgr|emp|cxl|auth|peer|lv|non|ov|e2e|set)[0-9]{13}$'
       or employee_code ~ '^(set|pwd)[0-9]{6}$'
       or employee_code ~ '^[a-z0-9]{2,6}-999[0-9]{7}$'
       or employee_code ~ '^999[0-9]{7}$';

  -- FR-42: drop approval steps naming one of these accounts first, or the
  -- foreign key refuses the delete below. Scoped to junk ids only — a step
  -- naming a real employee is never touched.
  delete from public.approval_steps s
   using _e2e_junk j
   where s.approver_id = j.id;
  get diagnostics v_steps = row_count;

  with del as (
    delete from auth.users u using _e2e_junk j where u.id = j.id returning u.id
  )
  select count(*) into v_count from del;

  if v_count > 0 or v_steps > 0 then
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_uid, 'cleanup_e2e_users', 'auth.users', null,
            jsonb_build_object('deleted', v_count, 'approval_steps_removed', v_steps));
  end if;

  return v_count;
end;
$_$;


--
-- Name: app_create_employee(text, text, text, uuid, uuid, uuid, public.app_role[], date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_create_employee(p_personnel_no text, p_full_name text, p_password text, p_company_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_manager_id uuid DEFAULT NULL::uuid, p_roles public.app_role[] DEFAULT ARRAY['employee'::public.app_role], p_hire_date date DEFAULT NULL::date, p_language_pref text DEFAULT 'fa'::text, p_calendar_pref text DEFAULT 'jalali'::text, p_job_title text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_caller uuid := auth.uid();
  v_admin  boolean;
  v_hr     boolean;
  v_dept   uuid;
  v_mgr    uuid;
  v_roles  public.app_role[];
  v_company uuid;
  v_uid    uuid;
  lt       record;
begin
  if v_caller is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_admin := private.is_admin(v_caller);
  v_hr := private.has_role(v_caller, 'hr');

  if v_admin then
    -- Tenant binding: an admin names the company, but only their own.
    if p_company_id is distinct from
       (select company_id from public.profiles where id = v_caller) then
      raise exception 'not allowed to create employees in another company'
        using errcode = '42501';
    end if;
    v_dept := p_department_id;
    v_mgr := p_manager_id;
    v_roles := p_roles;
    v_company := p_company_id;
  elsif v_hr then
    -- FR-35 / spec D4. HR onboards into ANY department and sets the reporting
    -- line, which is what makes them useful. But the role list is overwritten
    -- here regardless of what the client sent, so an HR account can never mint a
    -- manager, another HR, security, or an admin. Checked before the manager
    -- branch so someone holding both roles gets the wider HR scope.
    --
    -- The company comes from the caller's own profile rather than the argument,
    -- matching the manager branch: only an admin may name the company.
    select company_id into v_company from public.profiles where id = v_caller;
    v_dept := p_department_id;
    v_mgr := p_manager_id;
    v_roles := array['employee']::public.app_role[];
  elsif private.has_role(v_caller, 'manager') then
    -- Managers onboard into their own team only; every privileged input is
    -- overwritten here regardless of what the client sent.
    select department_id, company_id into v_dept, v_company
      from public.profiles where id = v_caller;
    if v_dept is null then
      raise exception 'manager has no department' using errcode = '22023';
    end if;
    v_mgr := v_caller;
    v_roles := array['employee']::public.app_role[];
  else
    raise exception 'admin or manager role required' using errcode = '42501';
  end if;

  v_uid := private.create_employee_impl(
    v_caller, case when v_admin then 'admin' when v_hr then 'hr' else 'manager' end,
    v_company, v_dept, v_mgr, p_personnel_no, p_full_name, p_password,
    v_roles, p_hire_date, p_language_pref, p_calendar_pref, p_job_title);

  -- Manager and HR paths: default quotas immediately, no admin round-trip.
  -- (`not v_admin` is both of them.)
  if not v_admin then
    for lt in
      select id, default_annual_quota_days
        from public.leave_types
       where company_id = v_company and active and affects_balance
         and coalesce(default_annual_quota_days, 0) > 0
    loop
      perform private.allocate_leave_impl(
        v_caller, v_uid, lt.id,
        date_trunc('year', current_date)::date,
        (date_trunc('year', current_date) + interval '1 year - 1 day')::date,
        round(lt.default_annual_quota_days * private.company_minutes_per_day(v_company))::int);
    end loop;
  end if;

  return v_uid;
end; $$;


--
-- Name: app_create_separation(uuid, text, date, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_create_separation(p_employee_id uuid, p_reason text, p_last_working_day date, p_father_name text, p_birth_cert_no text, p_note text, p_rows jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_father  text := nullif(btrim(p_father_name), '');
  v_cert    text := nullif(btrim(p_birth_cert_no), '');
  v_note    text := nullif(btrim(p_note), '');
  v_hr_fa   text;
  v_hr_en   text;
  v_id      uuid;
  v_row     jsonb;
  v_i       integer := 0;
begin
  if p_employee_id = v_uid then
    raise exception 'cannot file a clearance form for yourself' using errcode = '42501';
  end if;
  perform private.separation_manageable(v_uid, v_company, p_employee_id);
  perform private.separation_check_fields(p_reason, p_last_working_day, v_note);
  if v_father is not null and char_length(v_father) > 100 then
    raise exception 'invalid father name' using errcode = '22023';
  end if;
  if v_cert is not null and v_cert !~ '^[0-9]{1,10}$' then
    raise exception 'invalid birth certificate number' using errcode = '22023';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('separation:' || p_employee_id::text, 0));
  if exists (select 1 from public.separations
              where employee_id = p_employee_id and status <> 'cancelled' and deactivated_at is null) then
    raise exception 'employee already has an open clearance form' using errcode = '23505';
  end if;
  -- The last active admin can never be switched off; refuse the form up front.
  if exists (select 1 from public.user_roles where user_id = p_employee_id and role = 'admin')
     and not exists (select 1 from public.profiles p
                       join public.user_roles r on r.user_id = p.id and r.role = 'admin'
                      where p.active and p.id <> p_employee_id) then
    raise exception 'cannot deactivate the last active admin' using errcode = '22023';
  end if;

  -- D8: personal info wins; what HR typed fills only what is missing there, and is
  -- written back so the profile is complete next time.
  update public.employee_personal_info
     set father_name   = coalesce(father_name, v_father),
         birth_cert_no = coalesce(birth_cert_no, v_cert)
   where employee_id = p_employee_id
     and ((father_name is null and v_father is not null)
          or (birth_cert_no is null and v_cert is not null));
  select coalesce(i.father_name, v_father), coalesce(i.birth_cert_no, v_cert)
    into v_father, v_cert
    from (select 1) one
    left join public.employee_personal_info i on i.employee_id = p_employee_id;

  insert into public.separations (company_id, employee_id, reason, last_working_day, hire_date,
                                  father_name, birth_cert_no, note, created_by)
  select v_company, p_employee_id, p_reason, p_last_working_day, p.hire_date,
         v_father, v_cert, v_note, v_uid
    from public.profiles p where p.id = p_employee_id
  returning id into v_id;

  select name_fa, name_en into v_hr_fa, v_hr_en
    from public.separation_units where company_id = v_company and kind = 'hr';
  insert into public.separation_signoffs (separation_id, is_hr, name_fa, name_en, sort_order)
  values (v_id, true, coalesce(v_hr_fa, 'مدیر اداری و منابع انسانی'),
          coalesce(v_hr_en, 'HR & administration'), 0);

  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;
    insert into public.separation_signoffs (separation_id, name_fa, name_en, department_id, signer_id, sort_order)
    values (v_id, btrim(v_row->>'name_fa'), btrim(v_row->>'name_en'),
            nullif(v_row->>'department_id', '')::uuid,
            private.separation_row_signer(v_company, p_employee_id, v_row), v_i);
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.create', 'separations', v_id,
          jsonb_build_object('employee_id', p_employee_id, 'reason', p_reason,
                             'last_working_day', p_last_working_day, 'rows', v_i + 1));

  perform private.apply_due_separations(v_id);
  return v_id;
end; $_$;


--
-- Name: app_export_personal_info(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_export_personal_info() RETURNS TABLE(personnel_no text, employee_code text, full_name text, active boolean, national_id text, birth_cert_no text, father_name text, birth_date date, birth_place text, gender text, marital_status text, bank_name text, bank_account_no text, sheba text, card_no text, mobile text, home_phone text, address text, postal_code text, emergency_name text, emergency_phone text, insurance_no text, education text, military_status text, children_count smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid;
  v_count   int;
begin
  if not private.has_permission(v_uid, 'personal_info.view') then
    raise exception 'not permitted to export personal info' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;

  select count(*) into v_count from public.employee_personal_info where company_id = v_company;
  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (v_uid, 'personal_info.export', 'employee_personal_info', null,
          jsonb_build_object('rows', v_count));

  return query
    select p.personnel_no, p.employee_code, p.full_name, p.active,
           i.national_id, i.birth_cert_no, i.father_name, i.birth_date, i.birth_place,
           i.gender, i.marital_status, i.bank_name, i.bank_account_no, i.sheba,
           i.card_no, i.mobile, i.home_phone, i.address, i.postal_code,
           i.emergency_name, i.emergency_phone, i.insurance_no, i.education,
           i.military_status, i.children_count
      from public.employee_personal_info i
      join public.profiles p on p.id = i.employee_id
     where i.company_id = v_company
     order by p.active desc, p.personnel_no nulls last, p.full_name;
end; $$;


--
-- Name: app_get_separation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_get_separation(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v jsonb;
begin
  if not private.can_read_separation(auth.uid(), p_id) then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  select jsonb_build_object(
           'id', s.id, 'status', s.status, 'reason', s.reason,
           'last_working_day', s.last_working_day, 'hire_date', s.hire_date,
           'father_name', s.father_name, 'birth_cert_no', s.birth_cert_no, 'note', s.note,
           'settlement_date', s.settlement_date, 'finance_note', s.finance_note,
           'finance_signed_at', s.finance_signed_at, 'finance_signed_by_name', fs.full_name,
           'deactivated_at', s.deactivated_at, 'created_at', s.created_at,
           'created_by_name', cb.full_name, 'cancelled_at', s.cancelled_at,
           'employee', jsonb_build_object(
             'id', p.id, 'name', p.full_name, 'personnel_no', p.personnel_no,
             'department_id', p.department_id, 'department_name_fa', d.name_fa,
             'department_name_en', d.name_en, 'active', p.active),
           'rows', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id', o.id, 'is_hr', o.is_hr, 'name_fa', o.name_fa, 'name_en', o.name_en,
                      'department_id', o.department_id, 'signer_id', o.signer_id,
                      'signer_name', sp.full_name, 'sort_order', o.sort_order,
                      'signed_by', o.signed_by, 'signed_by_name', sb.full_name,
                      'signed_at', o.signed_at, 'note', o.note)
                    order by o.is_hr desc, o.sort_order)
               from public.separation_signoffs o
               left join public.profiles sp on sp.id = o.signer_id
               left join public.profiles sb on sb.id = o.signed_by
              where o.separation_id = s.id), '[]'::jsonb))
    into v
    from public.separations s
    join public.profiles p on p.id = s.employee_id
    left join public.departments d on d.id = p.department_id
    left join public.profiles fs on fs.id = s.finance_signed_by
    left join public.profiles cb on cb.id = s.created_by
   where s.id = p_id;
  return v;
end; $$;


--
-- Name: app_import_personal_info(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_import_personal_info(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid      uuid := auth.uid();
  v_company  uuid;
  v_is_admin boolean := private.is_admin(auth.uid());
  v_row      jsonb;
  v_pno      text;
  v_target   uuid;
  v_updated  int := 0;
  v_fields   constant text[] := array[
    'national_id','birth_cert_no','father_name','birth_date','birth_place','gender',
    'marital_status','bank_name','bank_account_no','sheba','card_no','mobile','home_phone',
    'address','postal_code','emergency_name','emergency_phone','insurance_no','education',
    'military_status','children_count'];
  v_key      text;
begin
  if not private.has_permission(v_uid, 'personal_info.edit') then
    raise exception 'not permitted to import personal info' using errcode = '42501';
  end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if jsonb_array_length(p_rows) > 2000 then
    raise exception 'too many rows (max 2000)' using errcode = '22023';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;

  if (select count(distinct r->>'personnel_no') <> count(*) from jsonb_array_elements(p_rows) r) then
    raise exception 'duplicate personnel number in file' using errcode = '22023';
  end if;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_pno := v_row->>'personnel_no';
    select id into v_target from public.profiles
     where company_id = v_company and personnel_no = v_pno;
    if v_target is null then
      raise exception 'unknown personnel number: %', coalesce(v_pno, '(empty)') using errcode = '22023';
    end if;
    if not v_is_admin and exists (select 1 from public.user_roles
                                   where user_id = v_target and role = 'admin') then
      raise exception 'not permitted to edit an admin''s personal info: %', v_pno using errcode = '42501';
    end if;
    for v_key in select jsonb_object_keys(v_row) loop
      if v_key <> 'personnel_no' and not (v_key = any (v_fields)) then
        raise exception 'unknown field: %', v_key using errcode = '22023';
      end if;
    end loop;

    update public.employee_personal_info i set
      national_id     = coalesce(v_row->>'national_id', i.national_id),
      birth_cert_no   = coalesce(v_row->>'birth_cert_no', i.birth_cert_no),
      father_name     = coalesce(v_row->>'father_name', i.father_name),
      birth_date      = coalesce((v_row->>'birth_date')::date, i.birth_date),
      birth_place     = coalesce(v_row->>'birth_place', i.birth_place),
      gender          = coalesce(v_row->>'gender', i.gender),
      marital_status  = coalesce(v_row->>'marital_status', i.marital_status),
      bank_name       = coalesce(v_row->>'bank_name', i.bank_name),
      bank_account_no = coalesce(v_row->>'bank_account_no', i.bank_account_no),
      sheba           = coalesce(v_row->>'sheba', i.sheba),
      card_no         = coalesce(v_row->>'card_no', i.card_no),
      mobile          = coalesce(v_row->>'mobile', i.mobile),
      home_phone      = coalesce(v_row->>'home_phone', i.home_phone),
      address         = coalesce(v_row->>'address', i.address),
      postal_code     = coalesce(v_row->>'postal_code', i.postal_code),
      emergency_name  = coalesce(v_row->>'emergency_name', i.emergency_name),
      emergency_phone = coalesce(v_row->>'emergency_phone', i.emergency_phone),
      insurance_no    = coalesce(v_row->>'insurance_no', i.insurance_no),
      education       = coalesce(v_row->>'education', i.education),
      military_status = coalesce(v_row->>'military_status', i.military_status),
      children_count  = coalesce((v_row->>'children_count')::smallint, i.children_count)
     where i.employee_id = v_target;
    v_updated := v_updated + 1;
  end loop;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (v_uid, 'personal_info.import', 'employee_personal_info', null,
          jsonb_build_object('rows', v_updated));

  return jsonb_build_object('updated', v_updated);
end; $$;


--
-- Name: app_list_separations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_list_separations() RETURNS TABLE(id uuid, employee_id uuid, employee_name text, personnel_no text, department_name_fa text, department_name_en text, status text, reason text, last_working_day date, deactivated_at timestamp with time zone, created_at timestamp with time zone, rows_total integer, rows_signed integer, awaiting_me boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.id, s.employee_id, p.full_name, p.personnel_no, d.name_fa, d.name_en,
         s.status, s.reason, s.last_working_day, s.deactivated_at, s.created_at,
         (select count(*)::int from public.separation_signoffs o where o.separation_id = s.id),
         (select count(*)::int from public.separation_signoffs o where o.separation_id = s.id and o.signed_at is not null),
         s.employee_id <> auth.uid() and (
           (s.status = 'in_progress' and exists (
              select 1 from public.separation_signoffs o
               where o.separation_id = s.id and o.signed_at is null
                 and ((not o.is_hr and o.signer_id = auth.uid())
                      or (o.is_hr and (private.has_role(auth.uid(), 'hr') or private.is_admin(auth.uid()))))))
           or (s.status = 'awaiting_finance' and private.has_role(auth.uid(), 'finance')))
    from public.separations s
    join public.profiles p on p.id = s.employee_id
    left join public.departments d on d.id = p.department_id
   where private.can_read_separation(auth.uid(), s.id)
   order by s.created_at desc
   limit 500;
$$;


--
-- Name: app_save_separation_units(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_save_separation_units(p_units jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_unit    jsonb;
  v_id      uuid;
  v_kind    text;
  v_dept    uuid;
  v_signer  uuid;
  v_keep    uuid[] := '{}';
  v_i       integer := 0;
begin
  if not private.has_permission(v_uid, 'separations.manage') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if p_units is null or jsonb_typeof(p_units) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  insert into public.separation_units (company_id, kind, name_fa, name_en, sort_order)
  values (v_company, 'hr', 'مدیر اداری و منابع انسانی', 'HR & administration', 0)
  on conflict (company_id) where kind = 'hr' do nothing;

  for v_unit in select value from jsonb_array_elements(p_units) loop
    v_kind := v_unit->>'kind';
    if jsonb_typeof(v_unit) <> 'object'
       or coalesce(char_length(btrim(v_unit->>'name_fa')), 0) not between 1 and 100
       or coalesce(char_length(btrim(v_unit->>'name_en')), 0) not between 1 and 100 then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    if v_kind = 'hr' then
      update public.separation_units
         set name_fa = btrim(v_unit->>'name_fa'), name_en = btrim(v_unit->>'name_en')
       where company_id = v_company and kind = 'hr';
      continue;
    end if;
    if v_kind is null or v_kind not in ('department', 'own_department', 'person') then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    v_i := v_i + 1;
    v_dept   := case when v_kind = 'department' then nullif(v_unit->>'department_id', '')::uuid end;
    v_signer := case when v_kind = 'person' then nullif(v_unit->>'signer_id', '')::uuid end;
    if v_kind = 'department' and (v_dept is null or not exists (
         select 1 from public.departments where id = v_dept and company_id = v_company)) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    if v_signer is not null and not exists (
         select 1 from public.profiles where id = v_signer and company_id = v_company and active) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    v_id := nullif(v_unit->>'id', '')::uuid;
    if v_id is not null and exists (select 1 from public.separation_units
                                     where id = v_id and company_id = v_company and kind <> 'hr') then
      update public.separation_units
         set kind = v_kind, name_fa = btrim(v_unit->>'name_fa'), name_en = btrim(v_unit->>'name_en'),
             department_id = v_dept, signer_id = v_signer, sort_order = v_i,
             active = coalesce((v_unit->>'active')::boolean, true)
       where id = v_id;
    else
      insert into public.separation_units (company_id, kind, name_fa, name_en, department_id, signer_id, sort_order, active)
      values (v_company, v_kind, btrim(v_unit->>'name_fa'), btrim(v_unit->>'name_en'), v_dept, v_signer, v_i,
              coalesce((v_unit->>'active')::boolean, true))
      returning id into v_id;
    end if;
    v_keep := v_keep || v_id;
  end loop;

  delete from public.separation_units
   where company_id = v_company and kind <> 'hr' and not (id = any (v_keep));
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.units', 'separation_units', null, jsonb_build_object('units', v_i + 1));
end; $$;


--
-- Name: app_separation_balances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_separation_balances(p_id uuid) RETURNS TABLE(leave_type_id uuid, name_fa text, name_en text, balance_minutes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_emp uuid;
begin
  if not private.can_read_separation(v_uid, p_id) then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  select employee_id into v_emp from public.separations where id = p_id;
  return query
    select t.id, t.name_fa, t.name_en,
           coalesce((select l.balance_after_minutes from public.leave_ledger l
                      where l.employee_id = v_emp and l.leave_type_id = t.id
                      order by l.seq desc limit 1), 0)
      from public.leave_types t
      join public.profiles p on p.id = v_emp and p.company_id = t.company_id
     where t.active and t.affects_balance
     order by t.name_fa;
end; $$;


--
-- Name: app_separation_warnings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_separation_warnings(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
begin
  if not private.has_permission(v_uid, 'separations.manage') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_employee_id and company_id = v_company) then
    raise exception 'employee not found' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'pending_requests', (select count(*) from public.leave_requests
                          where employee_id = p_employee_id and status = 'pending'),
    'direct_reports', (select count(*) from public.profiles
                        where manager_id = p_employee_id and active),
    'departments_managed', (select count(*) from public.departments
                             where manager_id = p_employee_id),
    'approval_steps', (select count(*) from public.approval_steps
                        where approver_id = p_employee_id and active));
end; $$;


--
-- Name: app_set_employee_password(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_employee_password(p_user_id uuid, p_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rows int;
begin
  if not private.is_admin(auth.uid()) then
    raise exception 'only admins can reset passwords' using errcode = '42501';
  end if;
  if length(coalesce(p_password, '')) < 8 then
    raise exception 'new password must be at least 8 characters' using errcode = '22023';
  end if;
  if octet_length(coalesce(p_password, '')) > 72 then
    raise exception 'new password must be at most 72 ASCII characters' using errcode = '22023';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')),
         updated_at = now()
   where id = p_user_id;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;

  -- An admin resetting their own password chose it themselves.
  update public.profiles
     set must_change_password = (p_user_id <> auth.uid())
   where id = p_user_id;

  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (auth.uid(), 'reset_password', 'auth.users', p_user_id);
end;
$$;


--
-- Name: app_set_initial_password(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_initial_password(p_new text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_same boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.profiles where id = v_uid and must_change_password
  ) then
    raise exception 'password change is not required' using errcode = '22023';
  end if;
  if length(coalesce(p_new, '')) < 8 then
    raise exception 'new password must be at least 8 characters' using errcode = '22023';
  end if;
  if octet_length(coalesce(p_new, '')) > 72 then
    raise exception 'new password must be at most 72 ASCII characters' using errcode = '22023';
  end if;

  select encrypted_password = extensions.crypt(p_new, encrypted_password)
    into v_same
    from auth.users
   where id = v_uid;
  if coalesce(v_same, false) then
    raise exception 'new password must differ from the issued password' using errcode = '22023';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_new, extensions.gen_salt('bf')),
         updated_at = now()
   where id = v_uid;

  perform set_config('bj.password_flag_write', 'on', true);
  update public.profiles
     set must_change_password = false
   where id = v_uid;
  perform set_config('bj.password_flag_write', '', true);

  insert into public.audit_log(actor_id, action, entity, entity_id)
  values (v_uid, 'set_initial_password', 'auth.users', v_uid);
end;
$$;


--
-- Name: app_set_separation_signoffs(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_separation_signoffs(p_id uuid, p_rows jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  s         record;
  v_row     jsonb;
  v_row_id  uuid;
  v_keep    uuid[] := '{}';
  v_i       integer := 0;
  o         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status <> 'in_progress' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;

  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;
    v_row_id := nullif(v_row->>'id', '')::uuid;
    if v_row_id is null then
      insert into public.separation_signoffs (separation_id, name_fa, name_en, department_id, signer_id, sort_order)
      values (p_id, btrim(v_row->>'name_fa'), btrim(v_row->>'name_en'),
              nullif(v_row->>'department_id', '')::uuid,
              private.separation_row_signer(v_company, s.employee_id, v_row), v_i)
      returning id into v_row_id;
    else
      select * into o from public.separation_signoffs where id = v_row_id and separation_id = p_id;
      if not found or o.is_hr then
        raise exception 'invalid rows' using errcode = '22023';
      end if;
      if o.signed_at is not null then
        update public.separation_signoffs set sort_order = v_i where id = v_row_id;
      else
        update public.separation_signoffs
           set name_fa = btrim(v_row->>'name_fa'), name_en = btrim(v_row->>'name_en'),
               department_id = nullif(v_row->>'department_id', '')::uuid,
               signer_id = private.separation_row_signer(v_company, s.employee_id, v_row),
               sort_order = v_i
         where id = v_row_id;
      end if;
    end if;
    v_keep := v_keep || v_row_id;
  end loop;

  if exists (select 1 from public.separation_signoffs
              where separation_id = p_id and not is_hr and signed_at is not null
                and not (id = any (v_keep))) then
    raise exception 'signed rows cannot be changed' using errcode = '22023';
  end if;
  delete from public.separation_signoffs
   where separation_id = p_id and not is_hr and signed_at is null and not (id = any (v_keep));

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.rows', 'separations', p_id, jsonb_build_object('rows', v_i + 1));
  perform private.refresh_separation_status(p_id);
end; $$;


--
-- Name: app_set_user_roles(uuid, public.app_role[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_user_roles(p_user_id uuid, p_roles public.app_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid    uuid := auth.uid();
  v_before public.app_role[];
  v_after  public.app_role[] := coalesce(p_roles, '{}');
begin
  select coalesce(array_agg(role order by role), '{}') into v_before
    from public.user_roles where user_id = p_user_id;

  if private.is_admin(v_uid) then
    if p_user_id = v_uid and not ('admin' = any (v_after)) then
      raise exception 'cannot remove your own admin role' using errcode = '22023';
    end if;
  elsif private.has_permission(v_uid, 'roles.manager') then
    if p_user_id = v_uid then
      raise exception 'you cannot change your own roles' using errcode = '42501';
    end if;
    if not exists (
      select 1
        from public.profiles t
        join public.profiles c on c.id = v_uid and c.company_id = t.company_id
       where t.id = p_user_id
    ) then
      raise exception 'employee not found' using errcode = '42501';
    end if;
    if 'admin' = any (v_before) then
      raise exception 'only admins can change an admin''s roles' using errcode = '42501';
    end if;
    if exists (
      (select r from unnest(v_before) r except select r from unnest(v_after) r)
      union
      (select r from unnest(v_after) r except select r from unnest(v_before) r)
      except select 'manager'::public.app_role
    ) then
      raise exception 'only the manager role may be added or removed' using errcode = '42501';
    end if;
  else
    raise exception 'only admins can set roles' using errcode = '42501';
  end if;

  delete from public.user_roles where user_id = p_user_id;
  insert into public.user_roles (user_id, role)
    select p_user_id, unnest(v_after)
    on conflict do nothing;

  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'set_roles', 'user_roles', p_user_id,
          jsonb_build_object('roles', to_jsonb(v_before)),
          jsonb_build_object('roles', to_jsonb(v_after)));
end; $$;


--
-- Name: app_sign_separation_finance(uuid, text, boolean, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sign_separation_finance(p_id uuid, p_signature_data text, p_signature_authorized boolean, p_note text, p_settlement_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  s         record;
begin
  if not private.has_role(v_uid, 'finance') then
    raise exception 'not allowed to sign as finance' using errcode = '42501';
  end if;
  perform private.separation_check_signature(p_signature_data, p_signature_authorized);
  if v_note is not null and length(v_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  if s.employee_id = v_uid then
    raise exception 'you cannot sign your own clearance form' using errcode = '42501';
  end if;
  if s.status <> 'awaiting_finance' then
    raise exception 'form is not awaiting finance' using errcode = '22023';
  end if;

  update public.separations
     set status = 'completed', finance_signed_by = v_uid, finance_signed_at = now(),
         finance_signature_data = p_signature_data, finance_signature_consent_at = now(),
         finance_note = v_note,
         settlement_date = coalesce(p_settlement_date, (now() at time zone 'Asia/Tehran')::date)
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.finance', 'separations', p_id, null);
end; $$;


--
-- Name: app_sign_separation_row(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sign_separation_row(p_row_id uuid, p_signature_data text, p_signature_authorized boolean, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  o         record;
  s         record;
begin
  perform private.separation_check_signature(p_signature_data, p_signature_authorized);
  if v_note is not null and length(v_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;

  select * into s from public.separations
   where id = (select separation_id from public.separation_signoffs where id = p_row_id)
     and company_id = v_company
     for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  if s.employee_id = v_uid then
    raise exception 'you cannot sign your own clearance form' using errcode = '42501';
  end if;
  if s.status <> 'in_progress' then
    raise exception 'form is not open for signing' using errcode = '22023';
  end if;
  -- Re-read under the form lock: a concurrent signer may have just signed it.
  select * into o from public.separation_signoffs where id = p_row_id;
  if o.signed_at is not null then
    raise exception 'row already signed' using errcode = '22023';
  end if;
  if o.is_hr then
    -- A5: any hr holder or an admin signs the HR row.
    if not (private.has_role(v_uid, 'hr') or private.is_admin(v_uid)) then
      raise exception 'row is not yours to sign' using errcode = '42501';
    end if;
  elsif o.signer_id is null then
    raise exception 'row has no signer yet' using errcode = '22023';
  elsif o.signer_id <> v_uid then
    raise exception 'row is not yours to sign' using errcode = '42501';
  end if;

  update public.separation_signoffs
     set signed_by = v_uid, signed_at = now(), signature_data = p_signature_data,
         signature_consent_at = now(), note = v_note
   where id = p_row_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.sign', 'separation_signoffs', p_row_id,
          jsonb_build_object('separation_id', s.id));
  perform private.refresh_separation_status(s.id);
end; $$;


--
-- Name: app_update_separation(uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_update_separation(p_id uuid, p_reason text, p_last_working_day date, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  s         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status = 'cancelled' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if s.deactivated_at is not null then
    raise exception 'form already applied' using errcode = '22023';
  end if;
  perform private.separation_check_fields(p_reason, p_last_working_day, v_note);

  update public.separations
     set reason = p_reason, last_working_day = p_last_working_day, note = v_note
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'separation.update', 'separations', p_id,
          jsonb_build_object('reason', s.reason, 'last_working_day', s.last_working_day),
          jsonb_build_object('reason', p_reason, 'last_working_day', p_last_working_day));
  perform private.apply_due_separations(p_id);
end; $$;


--
-- Name: approve_leave_request(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_leave_request(p_id uuid, p_signature_data text, p_signature_authorized boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid        uuid := auth.uid();
  v_emp        uuid;
  v_company    uuid;
  v_kind       public.request_kind;
  v_type       uuid;
  v_minutes    int;
  v_status     public.leave_status;
  v_start      date;
  v_end        date;
  v_unit       public.leave_unit;
  v_st         time;
  v_et         time;
  v_repl       uuid;
  v_affects    boolean;
  v_is_paid    boolean;
  v_prev       int := 0;
  v_paid       int := 0;
  v_unpaid     int := 0;
  v_rows       int;
  v_consent_at timestamptz := now();
  v_is_admin   boolean;
  v_is_mgr     boolean;
  v_step_role  public.app_role;
  v_step_id    uuid;
  v_step_order int;
  v_total      int;
  v_remaining  int;
  v_enforce    boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_signature_authorized is not true then
    raise exception 'signature authorization is required' using errcode = '22023';
  end if;
  if p_signature_data is null or p_signature_data = '' then
    raise exception 'signature is required' using errcode = '22023';
  end if;
  if length(p_signature_data) not between 100 and 350000
     or mod(length(p_signature_data), 4) <> 2
     or p_signature_data !~ '^data:image/png;base64,iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$'
  then
    raise exception 'signature data is invalid' using errcode = '22023';
  end if;

  select employee_id, company_id, kind into v_emp, v_company, v_kind
    from public.leave_requests where id = p_id;
  if v_emp is null then
    raise exception 'request not found' using errcode = 'P0002';
  end if;

  v_is_admin := private.is_admin(v_uid);
  v_is_mgr := private.is_manager_of(v_uid, v_emp);

  -- Serialise the whole sequence per employee, not just the ledger write.
  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_emp::text, 0));

  select leave_type_id, requested_minutes, status, start_date, end_date,
         unit, start_time, end_time, replacement_id
    into v_type, v_minutes, v_status, v_start, v_end,
         v_unit, v_st, v_et, v_repl
    from public.leave_requests
   where id = p_id;

  if v_status <> 'pending' then
    raise exception 'only pending requests can be approved' using errcode = '22023';
  end if;

  select count(*) into v_total
    from public.approval_steps s
   where s.company_id = v_company and s.active and v_kind = any(s.applies_to) and private.step_applies(s.manager_scope, v_emp);

  if v_total = 0 then
    -- No chain configured: behave exactly as before this migration.
    if not (v_is_mgr or v_is_admin) then
      raise exception 'not allowed to decide this request' using errcode = '42501';
    end if;
    v_step_role := 'manager';
    v_step_order := 1;
  else
    -- The lowest-ordered outstanding step this caller is entitled to fill.
    select s.role, s.step_order, s.id into v_step_role, v_step_order, v_step_id
      from public.approval_steps s
     where s.company_id = v_company
       and s.active
       and v_kind = any(s.applies_to) and private.step_applies(s.manager_scope, v_emp)
       and not exists (
             select 1 from public.leave_request_approvals a
              where a.request_id = p_id
                and (a.step_id = s.id
                     or (a.step_id is null and a.step_role = s.role)))
       and (
             -- FR-42: a step reserved for one NAMED person is fillable only by
             -- that person, and only while their account is active. There is no
             -- admin override here, unlike a role step: naming someone means
             -- their signature specifically is required, and an admin who could
             -- sign in their place would make the naming advisory. A departed
             -- approver is fixed by editing the configuration (admin or hr),
             -- not by signing past them.
             case when s.approver_id is not null then
                    s.approver_id = v_uid and private.is_active(v_uid)
                  else
                    v_is_admin
                    or ((s.role = 'manager' and s.manager_scope = 'direct' and v_is_mgr) or (s.role = 'manager' and s.manager_scope = 'department' and private.is_department_manager_of(v_uid, v_emp)))
                    or (s.role <> 'manager' and private.has_role(v_uid, s.role))
             end
           )
       -- Nobody but an admin signs their own request.
       and (v_is_admin or v_emp <> v_uid)
     order by s.step_order, s.role
     limit 1;

    if v_step_role is null then
      -- Distinguish "already signed by you" from "not your step", because the
      -- two need different things from the person reading the message.
      if exists (
        select 1 from public.leave_request_approvals a
         where a.request_id = p_id
           and (a.approver_id = v_uid
                or exists (
                     select 1 from public.approval_steps s
                      where s.company_id = v_company and s.active
                        and v_kind = any(s.applies_to) and private.step_applies(s.manager_scope, v_emp)
                        and (a.step_id = s.id
                             or (a.step_id is null and a.step_role = s.role))
                        and case when s.approver_id is not null
                                 then s.approver_id = v_uid
                                 else ((s.role = 'manager' and s.manager_scope = 'direct' and v_is_mgr) or (s.role = 'manager' and s.manager_scope = 'department' and private.is_department_manager_of(v_uid, v_emp)))
                                      or (s.role <> 'manager'
                                          and private.has_role(v_uid, s.role))
                            end))
      ) then
        raise exception 'you have already signed this request' using errcode = '22023';
      end if;
      raise exception 'not allowed to decide this request' using errcode = '42501';
    end if;

    select coalesce(approval_order_enforced, false) into v_enforce
      from public.work_settings where company_id = v_company limit 1;

    if coalesce(v_enforce, false) then
      if exists (
        select 1 from public.approval_steps s
         where s.company_id = v_company and s.active
           and v_kind = any(s.applies_to) and private.step_applies(s.manager_scope, v_emp)
           and s.step_order < v_step_order
           and not exists (
                 select 1 from public.leave_request_approvals a
                  where a.request_id = p_id
                    and (a.step_id = s.id
                         or (a.step_id is null and a.step_role = s.role))
                    and a.decision = 'approved')
      ) then
        raise exception 'an earlier approval is still required' using errcode = '22023';
      end if;
    end if;
  end if;

  -- The unique (request_id, step_id) index is what actually stops double-signing;
  -- rows predating FR-42 are covered by the sibling index on (request_id, step_role).
  insert into public.leave_request_approvals (
    request_id, step_id, step_role, approver_id, decision, signature_data, signature_consent_at
  ) values (
    p_id, v_step_id, v_step_role, v_uid, 'approved', p_signature_data, v_consent_at
  );

  select count(*) into v_remaining
    from public.approval_steps s
   where s.company_id = v_company and s.active
     and v_kind = any(s.applies_to) and private.step_applies(s.manager_scope, v_emp)
     and not exists (
           select 1 from public.leave_request_approvals a
            where a.request_id = p_id
              and (a.step_id = s.id
                   or (a.step_id is null and a.step_role = s.role))
              and a.decision = 'approved');

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (
    v_uid, 'approve_leave_step', 'leave_requests', p_id,
    jsonb_build_object(
      'employee_id', v_emp,
      'step_role', v_step_role,
      'steps_remaining', v_remaining,
      'digital_signature_authorized', true,
      'signature_consent_at', v_consent_at
    )
  );

  -- Still waiting on someone else: the request stays pending and the ledger is
  -- untouched. This early return is the whole point of the chain.
  if v_remaining > 0 then
    return;
  end if;

  -- ── final step: everything FR-14 used to do on the single decision ────────
  if exists (
    select 1 from public.leave_requests r
     where r.employee_id = v_emp
       and r.id <> p_id
       and r.status = 'approved'
       and r.start_date <= v_end
       and r.end_date >= v_start
       and (
         r.unit = 'day' or v_unit = 'day'
         or (r.start_time < v_et and r.end_time > v_st)
       )
  ) then
    raise exception 'overlapping approved leave exists' using errcode = '22023';
  end if;

  if v_repl is not null
     and private.replacement_is_away(v_repl, v_start, v_end, v_unit, v_st, v_et)
  then
    raise exception 'replacement is on leave during this period' using errcode = '22023';
  end if;

  select affects_balance, is_paid into v_affects, v_is_paid
    from public.leave_types where id = v_type;

  if v_affects then
    v_prev := public.current_leave_balance(v_emp, v_type);
    v_paid := least(v_minutes, greatest(v_prev, 0));
    v_unpaid := v_minutes - v_paid;
  elsif v_type is not null and not coalesce(v_is_paid, false) then
    v_unpaid := v_minutes;
  end if;

  update public.leave_requests
     set status = 'approved',
         unpaid_minutes = v_unpaid,
         decided_by = v_uid,
         decided_at = v_consent_at,
         -- Legacy columns keep the pre-chain readers working (the existing
         -- approver-signature viewer, the calendar metadata query). They record
         -- whoever COMPLETED the chain; the per-step evidence lives in
         -- leave_request_approvals.
         approver_signature_data = p_signature_data,
         approver_signature_consent_at = v_consent_at
   where id = p_id
     and status = 'pending';
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'request was already decided' using errcode = '22023';
  end if;

  if v_affects and v_paid > 0 then
    insert into public.leave_ledger(
      employee_id, leave_type_id, request_id, entry_type,
      delta_minutes, balance_after_minutes, note
    ) values (
      v_emp, v_type, p_id, 'consumption',
      -v_paid, v_prev - v_paid, 'paid portion consumed on approval'
    );
  end if;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (
    v_uid, 'approve_leave_request', 'leave_requests', p_id,
    jsonb_build_object(
      'employee_id', v_emp,
      'requested_minutes', v_minutes,
      'paid_minutes', v_paid,
      'unpaid_minutes', v_unpaid,
      'affects_balance', coalesce(v_affects, false),
      'replacement_id', v_repl,
      'completed_by_step', v_step_role,
      'digital_signature_authorized', true,
      'signature_consent_at', v_consent_at
    )
  );
end;
$_$;


--
-- Name: cancel_leave_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_leave_request(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_status public.leave_status;
  v_start date;
  v_type uuid;
  v_kind public.request_kind;
  v_minutes int;
  v_unpaid int;
  v_paid int;
  v_affects boolean;
  v_prev int;
  v_rows int;
  v_today date := (now() at time zone 'Asia/Tehran')::date;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  select employee_id into v_owner from public.leave_requests where id = p_id;
  if v_owner is null then raise exception 'request not found' using errcode = 'P0002'; end if;
  if not (v_owner = v_uid or private.is_admin(v_uid)) then
    raise exception 'not allowed to cancel this request' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_owner::text, 0));

  select status, start_date, leave_type_id, requested_minutes, unpaid_minutes, kind
    into v_status, v_start, v_type, v_minutes, v_unpaid, v_kind
    from public.leave_requests where id = p_id;
  v_paid := greatest(v_minutes - coalesce(v_unpaid, 0), 0);

  if v_status = 'pending' then
    update public.leave_requests
       set status = 'cancelled', decided_by = v_uid, decided_at = now()
     where id = p_id and status = 'pending';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'request was already decided' using errcode = '22023';
    end if;
  elsif v_status = 'approved'
        and (v_start > v_today or (v_kind = 'errand' and v_start >= v_today))
  then
    update public.leave_requests
       set status = 'cancelled', decided_by = v_uid, decided_at = now()
     where id = p_id and status = 'approved';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'request was already decided' using errcode = '22023';
    end if;

    select affects_balance into v_affects from public.leave_types where id = v_type;
    if v_affects and v_paid > 0 then
      v_prev := public.current_leave_balance(v_owner, v_type);
      insert into public.leave_ledger(
        employee_id, leave_type_id, request_id, entry_type,
        delta_minutes, balance_after_minutes, note
      ) values (
        v_owner, v_type, p_id, 'reversal',
        v_paid, v_prev + v_paid, 'paid portion reversed on cancel'
      );
    end if;
  else
    raise exception 'only pending or not-yet-started approved requests can be cancelled'
      using errcode = '22023';
  end if;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (
    v_uid, 'cancel_leave_request', 'leave_requests', p_id,
    jsonb_build_object(
      'status_before', v_status,
      'requested_minutes', v_minutes,
      'paid_minutes_reversed', case when v_status = 'approved' then v_paid else 0 end,
      'unpaid_minutes', v_unpaid,
      'kind', v_kind,
      'reversed', (
        v_status = 'approved' and coalesce(v_affects, false) and v_paid > 0
      )
    )
  );
end;
$$;


--
-- Name: compute_requested_minutes(uuid, date, date, public.day_part, public.leave_unit, time without time zone, time without time zone, public.request_kind); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_requested_minutes(p_company_id uuid, p_start date, p_end date, p_day_part public.day_part, p_unit public.leave_unit DEFAULT 'day'::public.leave_unit, p_start_time time without time zone DEFAULT NULL::time without time zone, p_end_time time without time zone DEFAULT NULL::time without time zone, p_kind public.request_kind DEFAULT 'leave'::public.request_kind) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_per_day numeric;
  v_count numeric := 0;
  d date;
  v_working boolean;
begin
  if p_end < p_start then return 0; end if;

  select hours_per_day into v_per_day
    from public.work_settings where company_id = p_company_id limit 1;
  if v_per_day is null then v_per_day := 8; end if;

  if p_unit = 'hour' then
    if p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
      return 0;
    end if;
    if p_kind = 'errand' then
      return (extract(epoch from (p_end_time - p_start_time)) / 60)::int;
    end if;

    v_working := (not private.is_company_weekend(p_company_id, p_start))
                 and not exists (
                   select 1 from public.holidays h
                    where h.company_id = p_company_id and h.holiday_date = p_start
                 );
    if not v_working then return 0; end if;
    return (extract(epoch from (p_end_time - p_start_time)) / 60)::int;
  end if;

  if p_kind = 'errand' then
    return round(((p_end - p_start) + 1) * v_per_day * 60);
  end if;

  if p_day_part in ('am', 'pm') then
    if p_start <> p_end then return 0; end if;
    v_working := (not private.is_company_weekend(p_company_id, p_start))
                 and not exists (
                   select 1 from public.holidays h
                    where h.company_id = p_company_id and h.holiday_date = p_start
                 );
    return case when v_working then round(v_per_day * 60 / 2) else 0 end;
  end if;

  d := p_start;
  while d <= p_end loop
    if (not private.is_company_weekend(p_company_id, d))
       and not exists (
         select 1 from public.holidays h
          where h.company_id = p_company_id and h.holiday_date = d
       )
    then
      v_count := v_count + 1;
    end if;
    d := d + 1;
  end loop;

  return round(v_count * v_per_day * 60);
end;
$$;


--
-- Name: current_leave_balance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_leave_balance(p_employee_id uuid, p_leave_type_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select balance_after_minutes from public.leave_ledger
    where employee_id = p_employee_id and leave_type_id = p_leave_type_id
    order by seq desc limit 1
  ), 0);
$$;


--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  claims jsonb;
  roles  jsonb;
  locale text;
begin
  select coalesce(jsonb_agg(role order by role), '[]'::jsonb)
    into roles
    from public.user_roles
   where user_id = (event->>'user_id')::uuid;

  select p.language_pref
    into locale
    from public.profiles p
   where p.id = (event->>'user_id')::uuid;

  claims := jsonb_set(coalesce(event->'claims', '{}'::jsonb), '{app_roles}', roles);

  -- Constrain to the locales the app actually routes. A junk value here would
  -- become a URL path segment in the middleware; lib/i18n/locale.ts rejects
  -- anything unknown as well, but emitting a bad claim in the first place is
  -- worse than pinning it to the default.
  claims := jsonb_set(
    claims,
    '{app_locale}',
    to_jsonb(case when locale in ('fa', 'en') then locale else 'fa' end)
  );

  return jsonb_set(event, '{claims}', claims);
end;
$$;


--
-- Name: get_my_cover_conflicts(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_cover_conflicts(p_start date, p_end date) RETURNS TABLE(request_id uuid, employee_name text, start_date date, end_date date, unit public.leave_unit, start_time time without time zone, end_time time without time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.id, p.full_name, r.start_date, r.end_date, r.unit, r.start_time, r.end_time
    from public.leave_requests r
    join public.profiles p on p.id = r.employee_id
   where private.is_active(auth.uid())
     and r.replacement_id = auth.uid()
     and r.status in ('pending', 'approved')
     and r.start_date <= p_end
     and r.end_date >= p_start
   order by r.start_date;
$$;


--
-- Name: get_my_team_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_team_directory() RETURNS TABLE(profile_id uuid, full_name text, employee_code text, relation text, roles public.app_role[], department_name_fa text, department_name_en text, manager_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select id, company_id, department_id, manager_id
      from public.profiles
     where id = auth.uid()
       and active
  )
  select
    p.id,
    p.full_name,
    p.employee_code,
    case when p.id = me.manager_id then 'manager' else 'teammate' end,
    coalesce(
      array_agg(ur.role order by ur.role) filter (where ur.role is not null),
      array[]::public.app_role[]
    ),
    d.name_fa,
    d.name_en,
    mgr.full_name
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
   and p.id <> me.id
   and (
     p.id = me.manager_id
     or (me.department_id is not null and p.department_id = me.department_id)
   )
  left join public.user_roles ur on ur.user_id = p.id
  left join public.departments d on d.id = p.department_id
  left join public.profiles mgr on mgr.id = p.manager_id
  group by p.id, p.full_name, p.employee_code, me.manager_id,
           d.name_fa, d.name_en, mgr.full_name
  order by case when p.id = me.manager_id then 0 else 1 end, p.full_name;
$$;


--
-- Name: get_org_chart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_chart() RETURNS TABLE(profile_id uuid, full_name text, job_title text, department_id uuid, department_name_fa text, department_name_en text, manager_id uuid, is_department_manager boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select company_id
      from public.profiles
     where id = auth.uid()
       and active
  )
  select
    p.id,
    p.full_name,
    p.job_title,
    p.department_id,
    d.name_fa,
    d.name_en,
    case when m.active then p.manager_id end,
    exists (
      select 1 from public.departments dm
       where dm.manager_id = p.id and dm.company_id = p.company_id
    )
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
  left join public.departments d on d.id = p.department_id
  left join public.profiles m on m.id = p.manager_id
  order by p.full_name;
$$;


--
-- Name: get_replacement_candidates(date, date, public.leave_unit, time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_replacement_candidates(p_start date, p_end date, p_unit public.leave_unit DEFAULT 'day'::public.leave_unit, p_start_time time without time zone DEFAULT NULL::time without time zone, p_end_time time without time zone DEFAULT NULL::time without time zone) RETURNS TABLE(profile_id uuid, full_name text, employee_code text, unavailable boolean, unavailable_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select id, company_id, department_id
      from public.profiles
     where id = auth.uid()
       and active
  )
  select
    p.id,
    p.full_name,
    p.employee_code,
    private.replacement_is_away(
      p.id, p_start, p_end, p_unit, p_start_time, p_end_time
    ) as unavailable,
    case
      when private.replacement_is_away(
        p.id, p_start, p_end, p_unit, p_start_time, p_end_time
      ) then 'on leave'
      else null
    end as unavailable_reason
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
   and p.id <> me.id
   and me.department_id is not null
   and p.department_id = me.department_id
  order by p.full_name;
$$;


