SET default_table_access_method = heap;

--
-- Name: jalali_months; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.jalali_months (
    jalali_year integer NOT NULL,
    jalali_month integer NOT NULL,
    gregorian_start date NOT NULL,
    gregorian_end date NOT NULL,
    CONSTRAINT jalali_months_jalali_month_check CHECK (((jalali_month >= 1) AND (jalali_month <= 12))),
    CONSTRAINT jalali_months_range CHECK ((gregorian_end >= gregorian_start))
);


--
-- Name: jalali_month_of(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jalali_month_of(p_date date) RETURNS public.jalali_months
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare v_row public.jalali_months;
begin
  select * into v_row from public.jalali_months
   where p_date between gregorian_start and gregorian_end;
  if v_row is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;
  return v_row;
end; $$;


--
-- Name: reject_leave_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_leave_request(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid       uuid := auth.uid();
  v_emp       uuid;
  v_company   uuid;
  v_kind      public.request_kind;
  v_status    public.leave_status;
  v_rows      int;
  v_note      text := nullif(btrim(coalesce(p_reason, '')), '');
  v_is_admin  boolean;
  v_is_mgr    boolean;
  v_step_role public.app_role;
  v_step_id   uuid;
  v_total     int;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;

  if length(v_note) > 500 then
    raise exception 'rejection note is too long (max 500 characters)' using errcode = '22023';
  end if;

  select employee_id, company_id, kind, status
    into v_emp, v_company, v_kind, v_status
    from public.leave_requests where id = p_id;
  if v_emp is null then raise exception 'request not found' using errcode = 'P0002'; end if;

  v_is_admin := private.is_admin(v_uid);
  v_is_mgr := private.is_manager_of(v_uid, v_emp);

  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_emp::text, 0));

  select count(*) into v_total
    from public.approval_steps s
   where s.company_id = v_company and s.active and v_kind = any(s.applies_to) and private.step_applies(s.manager_scope, v_emp);

  if v_total = 0 then
    if not (v_is_mgr or v_is_admin) then
      raise exception 'not allowed to decide this request' using errcode = '42501';
    end if;
    v_step_role := 'manager';
  else
    select s.role, s.id into v_step_role, v_step_id
      from public.approval_steps s
     where s.company_id = v_company and s.active
       and v_kind = any(s.applies_to) and private.step_applies(s.manager_scope, v_emp)
       and not exists (
             select 1 from public.leave_request_approvals a
              where a.request_id = p_id
                and (a.step_id = s.id
                     or (a.step_id is null and a.step_role = s.role)))
       and (
             -- FR-42: a step reserved for one NAMED person is fillable only by
             -- that person, and only while their account is active. There is no
             -- admin override here, unlike a role step: naming someone means
             -- their signature specifically is required, and an admin who could
             -- sign in their place would make the naming advisory. A departed
             -- approver is fixed by editing the configuration (admin or hr),
             -- not by signing past them.
             case when s.approver_id is not null then
                    s.approver_id = v_uid and private.is_active(v_uid)
                  else
                    v_is_admin
                    or ((s.role = 'manager' and s.manager_scope = 'direct' and v_is_mgr) or (s.role = 'manager' and s.manager_scope = 'department' and private.is_department_manager_of(v_uid, v_emp)))
                    or (s.role <> 'manager' and private.has_role(v_uid, s.role))
             end
           )
       and (v_is_admin or v_emp <> v_uid)
     order by s.step_order, s.role
     limit 1;

    if v_step_role is null then
      raise exception 'not allowed to decide this request' using errcode = '42501';
    end if;
  end if;

  if v_status <> 'pending' then
    raise exception 'only pending requests can be rejected' using errcode = '22023';
  end if;

  insert into public.leave_request_approvals (
    request_id, step_id, step_role, approver_id, decision, note
  ) values (
    p_id, v_step_id, v_step_role, v_uid, 'rejected', v_note
  );

  update public.leave_requests
     set status = 'rejected', decided_by = v_uid, decided_at = now(), decision_note = v_note
   where id = p_id and status = 'pending';
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then raise exception 'request was already decided' using errcode = '22023'; end if;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (v_uid, 'reject_leave_request', 'leave_requests', p_id,
          jsonb_build_object('employee_id', v_emp, 'step_role', v_step_role, 'reason', v_note));
end;
$$;


--
-- Name: search_approver_candidates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_approver_candidates(p_query text) RETURNS TABLE(id uuid, full_name text, personnel_no text, employee_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_company uuid;
  v_q text := btrim(coalesce(p_query, ''));
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if not (private.is_admin(v_uid) or private.has_role(v_uid, 'hr')) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;

  select company_id into v_company from public.profiles where public.profiles.id = v_uid;

  return query
    select p.id, p.full_name, p.personnel_no, p.employee_code
      from public.profiles p
     where p.company_id = v_company
       and p.active
       and (
         v_q = ''
         or p.full_name ilike '%' || v_q || '%'
         or p.personnel_no ilike v_q || '%'
         or p.employee_code ilike v_q || '%'
       )
     order by p.full_name
     limit 20;
end;
$$;


--
-- Name: set_employee_leave_policy(uuid, uuid, integer, integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_employee_leave_policy(p_employee_id uuid, p_leave_type_id uuid, p_accrual_minutes_per_month integer, p_annual_cap_minutes integer, p_carryover_cap_minutes integer, p_accrual_start_month date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  -- FR-43: admin OR hr. HR administers leave, so the two screens that set an
  -- opening balance and an accrual policy are theirs as well.
  if not (private.is_admin(auth.uid()) or private.has_role(auth.uid(), 'hr')) then
    raise exception 'only admins or hr can set a leave policy' using errcode = '42501';
  end if;
  -- ...but nobody except an admin does it to THEMSELVES. Same asymmetry FR-36
  -- already applies to signing your own request: an admin is the owner and may,
  -- an HR officer granting themselves leave is an obvious control weakness.
  if not private.is_admin(auth.uid()) and p_employee_id = auth.uid() then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;
  if p_accrual_minutes_per_month is null or p_accrual_minutes_per_month < 0 then
    raise exception 'accrual per month must be 0 or more' using errcode = '22023';
  end if;
  if p_carryover_cap_minutes is null or p_carryover_cap_minutes < 0 then
    raise exception 'carryover cap must be 0 or more' using errcode = '22023';
  end if;
  if p_annual_cap_minutes is not null and p_annual_cap_minutes < 0 then
    raise exception 'annual cap must be 0 or more' using errcode = '22023';
  end if;
  if not exists (select 1 from public.jalali_months where gregorian_start = p_accrual_start_month) then
    raise exception 'accrual start month must be a jalali month start' using errcode = '22023';
  end if;

  insert into public.employee_leave_policies as elp (
    employee_id, leave_type_id, accrual_minutes_per_month,
    annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
  ) values (
    p_employee_id, p_leave_type_id, p_accrual_minutes_per_month,
    p_annual_cap_minutes, p_carryover_cap_minutes, p_accrual_start_month, auth.uid()
  )
  on conflict (employee_id, leave_type_id) do update
     set accrual_minutes_per_month = excluded.accrual_minutes_per_month,
         annual_cap_minutes        = excluded.annual_cap_minutes,
         carryover_cap_minutes     = excluded.carryover_cap_minutes,
         accrual_start_month       = excluded.accrual_start_month
  returning elp.id into v_id;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'set_employee_leave_policy', 'employee_leave_policies', v_id,
          jsonb_build_object('employee_id', p_employee_id, 'leave_type_id', p_leave_type_id,
                             'accrual_minutes_per_month', p_accrual_minutes_per_month,
                             'annual_cap_minutes', p_annual_cap_minutes,
                             'carryover_cap_minutes', p_carryover_cap_minutes,
                             'accrual_start_month', p_accrual_start_month));
  return v_id;
end; $$;


--
-- Name: set_leave_balance(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_leave_balance(p_employee_id uuid, p_leave_type_id uuid, p_target_minutes integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_current int;
  v_ledger uuid;
begin
  -- FR-43: admin OR hr. HR administers leave, so the two screens that set an
  -- opening balance and an accrual policy are theirs as well.
  if not (private.is_admin(auth.uid()) or private.has_role(auth.uid(), 'hr')) then
    raise exception 'only admins or hr can set leave balance' using errcode = '42501';
  end if;
  -- ...but nobody except an admin does it to THEMSELVES. Same asymmetry FR-36
  -- already applies to signing your own request: an admin is the owner and may,
  -- an HR officer granting themselves leave is an obvious control weakness.
  if not private.is_admin(auth.uid()) and p_employee_id = auth.uid() then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;

  -- FR-48: a balance may be negative (leave taken in advance). Bounded at one
  -- year of workdays below zero so a typo cannot post an absurd debit.
  if p_target_minutes is null
     or p_target_minutes < -366 * private.company_minutes_per_day(
          (select company_id from public.profiles where id = p_employee_id)) then
    raise exception 'target balance is out of range' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee_id::text, 0));

  v_current := public.current_leave_balance(p_employee_id, p_leave_type_id);

  if v_current = p_target_minutes then
    return p_target_minutes;
  end if;

  insert into public.leave_ledger(employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
  values (p_employee_id, p_leave_type_id, 'adjustment', p_target_minutes - v_current, p_target_minutes, 'admin balance set')
  returning id into v_ledger;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'set_leave_balance', 'leave_ledger', v_ledger,
          jsonb_build_object('employee_id', p_employee_id, 'leave_type_id', p_leave_type_id,
                             'previous_minutes', v_current, 'target_minutes', p_target_minutes));

  return p_target_minutes;
end; $$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: submit_daily_errand_request(date, date, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_daily_errand_request(p_start date, p_end date, p_location text, p_signature_data text, p_signature_authorized boolean, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id uuid;
begin
  if not private.is_active(auth.uid()) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  v_request_id := private.submit_leave_impl(
    null::uuid, p_start, p_end, 'full', p_description,
    'day', null::time, null::time, null::uuid, 'errand', p_location
  );
  perform private.attach_request_signature(
    v_request_id, p_signature_data, p_signature_authorized
  );
  return v_request_id;
end;
$$;


--
-- Name: submit_errand_request(date, time without time zone, time without time zone, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_errand_request(p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location text, p_signature_data text, p_signature_authorized boolean, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id uuid;
begin
  if not private.is_active(auth.uid()) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  v_request_id := private.submit_leave_impl(
    null::uuid, p_date, p_date, 'full', p_description,
    'hour', p_start_time, p_end_time, null::uuid, 'errand', p_location
  );
  perform private.attach_request_signature(
    v_request_id, p_signature_data, p_signature_authorized
  );
  return v_request_id;
end;
$$;


--
-- Name: submit_hourly_leave_request(uuid, date, time without time zone, time without time zone, text, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_hourly_leave_request(p_leave_type_id uuid, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_signature_data text, p_signature_authorized boolean, p_reason text DEFAULT NULL::text, p_replacement_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id uuid;
begin
  if not private.is_active(auth.uid()) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  v_request_id := private.submit_leave_impl(
    p_leave_type_id, p_date, p_date, 'full', p_reason,
    'hour', p_start_time, p_end_time, p_replacement_id, 'leave', null
  );
  perform private.attach_request_signature(
    v_request_id, p_signature_data, p_signature_authorized
  );
  return v_request_id;
end;
$$;


--
-- Name: submit_leave_request(uuid, date, date, public.day_part, text, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_leave_request(p_leave_type_id uuid, p_start date, p_end date, p_day_part public.day_part, p_signature_data text, p_signature_authorized boolean, p_reason text DEFAULT NULL::text, p_replacement_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id uuid;
begin
  if not private.is_active(auth.uid()) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  v_request_id := private.submit_leave_impl(
    p_leave_type_id, p_start, p_end, p_day_part, p_reason,
    'day', null, null, p_replacement_id, 'leave', null
  );
  perform private.attach_request_signature(
    v_request_id, p_signature_data, p_signature_authorized
  );
  return v_request_id;
end;
$$;


