CREATE TABLE public.user_roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    role public.app_role NOT NULL
);


--
-- Name: user_signatures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_signatures (
    user_id uuid NOT NULL,
    signature_data text NOT NULL,
    source text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_signatures_shape CHECK ((((length(signature_data) >= 100) AND (length(signature_data) <= 350000)) AND (mod(length(signature_data), 4) = 2) AND (signature_data ~ '^data:image/png;base64,iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$'::text))),
    CONSTRAINT user_signatures_source CHECK ((source = ANY (ARRAY['drawn'::text, 'upload'::text])))
);


--
-- Name: TABLE user_signatures; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.user_signatures IS 'FR-52: one saved signature per user. Owner-only by RLS (no admin path). Requests keep their own copy.';


--
-- Name: work_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    weekend_days integer[] DEFAULT '{5}'::integer[] NOT NULL,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    hours_per_day numeric DEFAULT 8 NOT NULL,
    work_start time without time zone DEFAULT '07:00:00'::time without time zone NOT NULL,
    work_end time without time zone DEFAULT '15:00:00'::time without time zone NOT NULL,
    max_hourly_minutes_per_day integer DEFAULT 240 NOT NULL,
    approval_order_enforced boolean DEFAULT false NOT NULL,
    biweekly_weekend_days integer[] DEFAULT '{}'::integer[] NOT NULL,
    biweekly_anchor date,
    CONSTRAINT work_settings_biweekly_anchor_required CHECK (((cardinality(COALESCE(biweekly_weekend_days, '{}'::integer[])) = 0) OR (biweekly_anchor IS NOT NULL))),
    CONSTRAINT work_settings_biweekly_days_valid CHECK (((biweekly_weekend_days <@ ARRAY[1, 2, 3, 4, 5, 6, 7]) AND (NOT (ARRAY[1, 2, 3, 4, 5, 6, 7] <@ (COALESCE(weekend_days, '{}'::integer[]) || COALESCE(biweekly_weekend_days, '{}'::integer[])))))),
    CONSTRAINT work_settings_hourly_cap_sane CHECK (((max_hourly_minutes_per_day > 0) AND (max_hourly_minutes_per_day <= 1440))),
    CONSTRAINT work_settings_hours_per_day_sane CHECK (((hours_per_day > (0)::numeric) AND (hours_per_day <= (24)::numeric))),
    CONSTRAINT work_settings_window_sane CHECK ((work_end > work_start))
);


--
-- Name: COLUMN work_settings.approval_order_enforced; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_settings.approval_order_enforced IS 'FR-36: when true, a step cannot be signed until every lower-ordered active step has been. Ships false — any order, whoever is free.';


--
-- Name: COLUMN work_settings.biweekly_weekend_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_settings.biweekly_weekend_days IS 'FR-41: ISO weekday numbers that are off every OTHER week. Empty = feature unused.';


--
-- Name: COLUMN work_settings.biweekly_anchor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_settings.biweekly_anchor IS 'FR-41: any date whose week is an off week. Required whenever biweekly_weekend_days is non-empty.';


